var HOWTO = {"neon-demon-hunter": {"m": ["Streetwear outfit: black hoodie, black pants, chunky sneakers (make: from closet)", "Neon fabric paint in 2 to 3 colors (buy: craft store)", "Glow-in-the-dark temporary tattoos or neon eyeliner (buy: drugstore)", "Toy sword prop (buy: toy store)", "Hair gel or temporary neon hair spray (buy: drugstore)", "Black leather-look jacket or vest (buy: thrift store, optional)"], "s": ["Buy the neon fabric paint, temporary tattoos, toy sword prop, and hair spray. Lay the black hoodie, black pants, and chunky sneakers flat.", "Draw sharp neon symbols, lightning marks, and circles on the hoodie sleeves and pant legs with the neon fabric paint. Let the paint dry for 2 hours.", "Style the hair up with hair gel, or mist it with the temporary neon hair spray. Apply the neon eyeliner or glow-in-the-dark temporary tattoos on the cheeks and arms.", "Wear the black leather-look jacket over the hoodie and carry the toy sword prop. Keep the painted side facing out so the neon sigils show."]}, "classic-ghost": {"m": ["Old white sheet or white fabric (make: use an old sheet)", "Black marker (buy: dollar store)", "Scissors"], "s": ["Drape the old white sheet over the wearer.", "Lightly mark the eye positions with the black marker while they stand still.", "Take the sheet off. Cut out generous eye holes with the scissors and draw a wavy mouth below the eyes with the black marker.", "Safety: keep the sheet above the ankles and the eye holes generous, so walking and seeing stay easy.", "Drape the sheet back on and line up the eyes. Trim the bottom with the scissors so it clears the ground by a few inches."]}, "blue-dog-family": {"m": ["Blue or orange t-shirt per person (own, or buy: clothing store)", "Headband per person (buy: dollar store)", "Blue, orange, and white craft felt (buy: craft store, construction paper works too)", "Safety pins (buy: dollar store)", "Scissors"], "s": ["Buy the t-shirts, headbands, craft felt, and safety pins.", "Cut two floppy dog ears from the craft felt with the scissors for each person. Match ear color to shirt color.", "Pin the ears to each headband with the safety pins.", "Pin a white craft felt belly spot to the front of each blue or orange t-shirt.", "Pull on the blue or orange t-shirts.", "Put on the headbands and decide who is mama, dad, and the pups."]}, "superhero-family": {"m": ["Matching red sweatsuits, one per person (make: from closet, or buy a set at a discount store)", "Black felt sheet, 1 pack (buy: craft store; construction paper works too)", "Yellow felt sheet, 1 sheet (buy: craft store)", "1 plain headband per person (buy: dollar store multi-pack)", "Safety pins or tape (make: from home)", "Scissors (make: from home)"], "s": ["Buy the felt sheets and headbands.", "Have everyone dress in the red sweatsuits.", "Safety: cut the eye holes wide enough so everyone can see clearly.", "Make the eye masks: cut a mask strip from the black felt for each person with two eye holes. Attach it to the headband with the safety pins or tape.", "Make the logos: cut one big first-initial letter per person from the yellow felt. Use the safety pins or tape to attach it to the chest of each sweatsuit.", "Everyone wears the mask headband with the letter on the chest. Each person strikes their own hero pose for the group photo."]}, "blue-alien-ohana": {"m": ["Blue hoodie per alien-role person (own, or buy: clothing store)", "Blue craft felt, 1 sheet per alien (buy: craft store, construction paper works too)", "Headband per alien-role person (buy: dollar store)", "Red t-shirt or dress per Lilo-role person (make: from closet, or buy: thrift store)", "White craft felt or paper, 1 sheet (buy: craft store)", "Safety pins (buy: dollar store)", "Scissors", "Tape"], "s": ["Buy the blue craft felt, the headbands, the white felt or paper, and the safety pins.", "Cut two large oval ears from the blue craft felt for each alien-role person with the scissors.", "Tape one pair of ears to each headband with the tape.", "Pull on the blue hoodies.", "Lilo: cut leaf shapes from the white felt or paper with the scissors. Pin or glue the leaves across the red t-shirt or dress.", "Safety: pin from the front of the red shirt, so pin backs face the fabric and never the skin.", "Wear dark hair down for Lilo. Put the ear headbands on the aliens last."]}, "emerald-witch": {"m": ["1 long green dress or green fabric, 3 yards (buy: fabric store)", "1 sheet black cardboard for the hat (buy: craft store; a box painted black works too)", "Green face paint, non-toxic (buy: drugstore)", "Black eyeliner and dark green eye shadow (buy: drugstore)", "Hot glue and scissors", "1 broom from home for a prop (make: use what you own)"], "s": ["Buy the green fabric, black cardboard, green face paint, black eyeliner, and dark green eye shadow.", "Safety: let an adult handle the hot glue, since the nozzle and glue get very hot.", "Sew or hot glue the green fabric into a long gown, leaving the hem ragged.", "Roll the black cardboard into a tall cone, and glue a wide black cardboard brim to its base.", "Paint the face green with the green face paint. Draw on the black eyeliner and the dark green eye shadow.", "Carry the broom bristle-up so it does not trip anyone."]}, "gloom-bloom": {"m": ["Gloom: black clothes from your closet (make: use what you own)", "Bloom: colorful clothes from your closet (make: use what you own)", "Black and white face paint, non-toxic (buy: drugstore)", "Hair ties for braids (make: use what you own)", "Fake flowers (buy: dollar store; paper flowers work too)"], "s": ["Buy the black and white face paint and the fake flowers.", "Gloom: wear the black clothes, and braid the hair tightly with the hair ties.", "Paint a small black teardrop under one eye with the black and white face paint.", "Bloom: wear the colorful clothes, and pin the fake flowers in the hair.", "Paint a small flower on one cheek with the face paint, keeping it clear of the eyes.", "Stand side by side: Gloom frowns and looks away, Bloom smiles big."]}, "deadpan-diva": {"m": ["Black dress (own)", "Very pale foundation or white non-toxic face paint (buy: toy store)", "Dark eyeliner and lipstick (own, or buy: dollar store)", "2 hair ties (own)"], "s": ["Braid the hair into two tight braids with the hair ties.", "Buy the white non-toxic face paint if needed.", "Apply the pale foundation evenly over the face.", "Add the dark eyeliner and lipstick for contrast.", "Put on the black dress, fold the arms, and hold the stare.", "Use skin-safe makeup and wash it all off before bed."]}, "safari-zoo-crew": {"m": ["Solid-color clothes in animal colors from each person's closet (make: from closet)", "1 plastic headband per person (buy: dollar store multi-pack)", "Felt sheets in brown, black, pink, and tan, 1 pack (buy: craft store; construction paper works too)", "Face paint, brown and black (buy: costume aisle or craft store)", "Scissors and tape (make: from home)"], "s": ["Have each person pick one animal and pull matching solid-color clothes from the closet. Brown works for a bear, gray works for an elephant. Buy the plastic headband pack, felt sheets, and face paint.", "Safety: cut the felt slowly and keep fingers clear of the scissors.", "Make each animal's ears from felt: cut two rounded ears and tape them to a plastic headband.", "Safety: use non-toxic kids face paint, and keep it away from the eyes.", "Paint faces: use the face paint to add each animal's nose, whiskers, or spots.", "Wear the colored outfit and put on the ear headband. Add one felt detail, like a felt tail taped to the back, to complete each animal."]}, "fairy-tale-princesses": {"m": ["Each person: a dress from their closet (make: use what you own)", "1 cardboard crown per person (make: from a cereal box)", "Gold or silver paint or markers (buy: craft store)", "Scissors, tape", "Hair ribbon (buy: dollar store)"], "s": ["Buy the gold or silver markers and the hair ribbon.", "Each princess picks any dress from her own closet.", "Safety: adults handle the scissors when cutting the cardboard crowns.", "Cut a crown from a cereal box, and color it with the gold or silver paint or markers.", "Tie the hair ribbon as a bow, and tape the cardboard crown on top of the head.", "Line up for a princess parade photo, and check that each cardboard crown sits snugly."]}, "tin-hero": {"m": ["Red sweatsuit (make: from closet)", "Gold duct tape, 1 roll (buy: dollar store or hardware store)", "Battery tea light, 1 (buy: dollar store)", "Cardboard, 1 piece (make: from home)", "Tape (make: from home)", "Safety pin, 1 (make: from home)"], "s": ["Buy the gold duct tape and the battery tea light.", "Dress in the red sweatsuit.", "Stripe the sweatsuit with the gold duct tape: strips across the chest, arms, and legs.", "Make the chest reactor: cover a cardboard circle in gold tape. Tape the tea light behind its center.", "Safety: pin from inside the sweatsuit, so the pin back faces the fabric and never the skin.", "Pin the glowing circle to the chest of the sweatsuit.", "Walk like the suit does the talking."]}, "good-witch-bad-witch": {"m": ["Bad witch: black dress or black clothes (make: use your closet)", "Good witch: pink dress or pink clothes (make: use your closet)", "Green face paint, non-toxic (buy: drugstore)", "1 cardboard crown (make: from a cereal box)", "1 black cone hat (buy: dollar store)", "Hot glue, scissors, pink marker, tape"], "s": ["Buy the green face paint, the black cone hat, and the pink marker.", "Bad witch: wear the black dress or black clothes.", "Safety: let an adult handle the hot glue, and keep the green face paint away from the eyes.", "Hot glue a bent brim onto the black cone hat. Paint the bad witch's face and hands green with the green face paint.", "Good witch: wear the pink dress or pink clothes. Color the cardboard crown with the pink marker, and tape it on the head."]}, "fuzzy-monster": {"m": ["1 pastel fuzzy sweatsuit (buy: discount store)", "2 large googly eyes, 3 inches or bigger (buy: craft store; paper circles work too)", "White felt for the smile (buy: craft store; construction paper works too)", "Scissors, fabric glue or safety pins"], "s": ["Buy the pastel fuzzy sweatsuit, the googly eyes, and the white felt.", "Glue or pin the two googly eyes to the hood of the pastel fuzzy sweatsuit.", "Safety: adults handle the scissors when cutting the white felt.", "Cut a big stitched-style smile from the white felt, and glue it across the chest.", "Let the fabric glue dry fully before wearing.", "Wear the hood up so the googly eyes sit above the forehead."]}, "pocket-plush": {"m": ["Fuzzy one-piece pajamas or sweatsuit, 1 (buy: thrift store or closet)", "Felt ears: two big circles of felt (buy: craft store; construction paper works too)", "Fabric glue (buy: craft store)", "Black and white felt for eyes and smile (buy: craft store; paper works too)", "Large shipping tag or big index card (buy: office supply store)", "Marker (make: household)"], "s": ["Buy the fuzzy one-piece pajamas, felt ears, fabric glue, and large shipping tag. Glue the felt ears to the hood of the fuzzy one-piece pajamas.", "Cut two white felt eyes and a stitched-look smile from the black felt. Glue them to the chest of the fuzzy one-piece pajamas with the fabric glue.", "Write a collector number like 'No. 001' on the large shipping tag with the marker. Tie the tag to the wrist or waistband with string.", "Wear the fuzzy one-piece pajamas with the felt ears and large shipping tag showing. The smile goes on the chest like a plush's embroidered face."]}, "soccer-squad": {"m": ["Matching jerseys or same-color t-shirts, one per player (make: from closet, or buy a multi-pack at a sports store)", "Black shirt and black shorts for the referee (make: from closet)", "1 soccer ball, any size (buy: sports store, or make: borrow from home)", "Red cardstock rectangle, 3x4 inches (make: cut from a folder or colored paper)", "Black marker, 1 (make: from home)", "White athletic tape, 1 roll (buy: sports store or pharmacy)"], "s": ["Assign roles: most of the family are players, one person is the referee.", "Players: wear matching jerseys or same-color shirts. Wrap a strip of white athletic tape around one upper arm as a captain's armband. Referee: wear all black.", "Safety: cut the cardstock slowly and keep fingers clear of the scissors.", "Make the red card: cut the red cardstock rectangle from the folder or colored paper. Draw a thick black border around it with the black marker so it reads as a card at a glance.", "Players carry or dribble the soccer ball. The referee practices holding the red card high in the air."]}, "glow-skeleton": {"m": ["1 black sweatsuit (buy: discount store or use one you own)", "1 roll glow-in-the-dark bone tape or white tape (buy: craft store)", "1 pack glow bracelets (buy: dollar store)", "Scissors", "Black face paint, non-toxic (buy: drugstore)"], "s": ["Buy the black sweatsuit if you do not own one, plus the bone tape and glow bracelets.", "Charge the bone tape under a lamp for 20 minutes for maximum glow.", "Safety: adults handle the scissors when cutting the bone tape.", "Cut the bone tape into rib bones: lay strips horizontally across the chest and back. Add vertical spine segments down the center, and arm and leg bones down the limbs.", "Snap the glow bracelets onto both wrists and both ankles right before heading out.", "Paint simple skull eye circles with the black face paint, keeping clear of the eyes so vision stays clear."]}, "block-game-crew": {"m": ["1 large cardboard box per person (make: ask a grocery store for spares)", "Acrylic paint in each hero's colors (buy: craft store, tempera paint works too)", "Paintbrushes", "Black marker (buy: dollar store)", "Scissors"], "s": ["Each person picks a blocky video-game hero look.", "Safety: an adult should handle the heavy cutting, and cut the eye holes generously so everyone can see clearly.", "Cut a head opening and eye holes in each large cardboard box with the scissors.", "Paint each box in the hero's main colors with the acrylic paint and paintbrushes. Let it dry fully.", "Draw a pixel-style square face and details on the front of each box with the black marker. Wear the boxes over regular clothes once the paint is dry."]}, "web-slinger-crew": {"m": ["Hoodies in red, black, and pink, one per person (make: from closet)", "Black fabric paint or black face paint, 1 tube (buy: craft store)", "White stickers or white electrical tape, 1 roll (buy: hardware store)", "Sunglasses or swim goggles, one per person (buy: dollar store multi-pack)", "Tape (make: from home)"], "s": ["Assign each person a hoodie color.", "Buy the black fabric paint or black face paint, white stickers or white electrical tape, and the multi-pack of sunglasses.", "Stick white stickers or white electrical tape in a web pattern across the front of each pair of sunglasses. Draw two black eye lenses on top with the black fabric paint or black face paint. Let them dry flat for 30 minutes.", "Make the chest webs: stick short white tape strips in a web grid across the chest of each hoodie.", "Wear the hoodie with the hood up and put on the web-patterned sunglasses. Each person picks their own web-shooting pose for the group shot."]}, "mermaid-crew": {"m": ["T-shirt or dress in a sea color (teal, purple, red, white), 1 per person (buy: thrift store or closet)", "Face paint in a matching accent color (buy: drugstore)", "Plastic trident prop (buy: toy store)", "Toy crab or cardboard crab (make: cut one from red paper, or buy: toy store)", "Shell necklace (buy: craft store, or make: string pasta shells)", "Scissors and tape (make: household tools)"], "s": ["Buy the plastic trident prop and the face paint. Assign each person a role and a sea-colored t-shirt or dress from the closet.", "Each person: put on their sea-colored t-shirt or dress. Paint one small matching detail, like scales on a cheek, a seaweed swirl, or an anchor.", "Cut a red paper body, legs, and claws with the scissors and tape them to the smallest person's shirt. Or hand them the toy crab instead.", "The sea king carries the plastic trident prop. Everyone else picks one accessory, like the shell necklace, and stands tall for the crew photo."]}, "little-pig-family": {"m": ["Pink t-shirts or pajamas, one per person (buy: thrift store or closet)", "Pink headband, one per person (buy: dollar store)", "Pink paper cup, 1 per snout (make: from kitchen drawer)", "Pink felt or construction paper, 2 triangles per ear (buy: craft store)", "Pink string or yarn, 1 arm length per snout (make: from craft drawer)", "Scissors and clear tape (make: household tools)", "Pink blush or face paint for cheeks (buy: drugstore)"], "s": ["Buy the pink t-shirts and pink headbands. Gather the pink paper cups, pink felt, pink string, scissors, and clear tape from around the house.", "Poke two small holes in the sides of a pink paper cup.", "Cut two pink felt triangles and tape them to the pink headband as ears.", "Thread the pink string through the holes, then tie the cup gently in front of the nose.", "Dab a little pink blush on each person's cheeks with a finger. Hand the little brother a toy dinosaur from the toy store or one he owns. Now he is the pig who brings the dinosaur."]}, "enchanted-castle-crew": {"m": ["Princess: yellow dress or fabric, 2 yards (buy: fabric store)", "Prince: blue jacket and dark pants (make: use your closet)", "Candelabra: gold face paint and a gold headband (buy: craft store)", "Clock: brown cardboard circle and hands (make: from a box)", "Teapot: white pot or cardboard pot body (make: from a box)", "Hot glue, scissors, face paint"], "s": ["Buy the yellow fabric, gold face paint, and gold headband. Assign roles first so nobody builds the same prop twice.", "Princess: wrap and pin the yellow fabric as a simple gown. Prince: wear the blue jacket and dark pants with a sash of torn fabric.", "Safety: let an adult handle the hot glue, and keep the face paint away from the eyes.", "Candelabra: paint the face gold with the gold face paint, and glue three cardboard flame shapes to the gold headband.", "Safety: adults handle the scissors when cutting the cardboard.", "Clock: paint the brown cardboard circle cream and add painted hands. Teapot: cut a rounded cardboard pot body, add a handle and spout, and wear it over the shoulders."]}, "bumble-bee": {"m": ["Black sweatshirt and sweatpants (own, or buy: clothing store)", "Yellow duct or electrical tape (buy: dollar store)", "Black headband (buy: dollar store)", "2 yellow pipe cleaners (buy: craft store, floral wire works too)", "2 black pom-poms (buy: craft store, cotton balls work too)", "Craft glue (buy: craft store)"], "s": ["Buy the yellow duct or electrical tape, black headband, yellow pipe cleaners, black pom-poms, and craft glue.", "Wrap three yellow duct tape stripes around the torso of the black sweatshirt and one around each arm.", "Twist the two yellow pipe cleaners into a V.", "Safety: use non-toxic craft glue, and keep the pom-poms out of reach of toddlers.", "Glue a black pom-pom to each tip of the V with the craft glue. Glue the base of the V to the black headband.", "Let the glue dry fully, then pull on the black sweatshirt and sweatpants and the black headband."]}, "baby-dino": {"m": ["Green hoodie (buy: clothing store, or use your own)", "2 sheets green craft felt (buy: craft store, construction paper works too)", "Pillow stuffing or 2 old socks (make: stuff from home)", "Safety pins (buy: dollar store)", "Masking tape", "Scissors"], "s": ["Buy the green hoodie, green craft felt, and safety pins.", "Cut 6 to 8 triangle spikes from the green craft felt with the scissors.", "Tape the spikes in a row down the back of the green hoodie with the masking tape. Pin each spike from inside the hoodie with a safety pin.", "Stuff the old socks with the pillow stuffing and tape the open ends shut with the masking tape.", "Safety: pin everything from inside the green hoodie, so pin backs face the fabric and never the skin.", "Pin the stuffed tail to the back waistband of the green hoodie."]}, "little-lion": {"m": ["1 tan or brown sweatsuit (buy: discount store or use one you own)", "1 brown fuzzy fabric strip or old brown towel for the mane (buy: fabric store, or make from a towel)", "Scissors", "Safety pins or fabric glue", "Brown face paint, non-toxic (buy: drugstore)"], "s": ["Buy the tan sweatsuit and the brown fuzzy fabric strip.", "Safety: adults handle the scissors when cutting the brown fuzzy fabric.", "Cut the brown fuzzy fabric into a wide collar for the mane.", "Pin the mane around the hood or neckline of the tan sweatsuit with the safety pins, fluffing it outward.", "Paint a brown nose and whiskers with the brown face paint, keeping clear of the eyes.", "Pin the mane flat at the back so it does not slip over the eyes while the little lion runs."]}, "tiny-firefighter": {"m": ["Red sweatsuit (make: from closet)", "Toy firefighter helmet (buy: toy store)", "Toy fire hose or coiled garden hose (buy: toy store, or make: borrow a real coil of rope from home)", "Yellow reflective tape, 1 roll (buy: hardware store)", "Black marker, 1 (make: from home)"], "s": ["Buy the toy firefighter helmet, toy fire hose, and yellow reflective tape. Dress the kid in the red sweatsuit.", "Make the turnout stripes: wrap two horizontal bands of the yellow reflective tape around each sleeve and each leg. Press the tape firmly so it sticks.", "Safety: keep the toy firefighter helmet snug so it does not slide over the eyes.", "Put the toy firefighter helmet on and carry the toy fire hose coiled over one shoulder.", "Finishing touch: the kid holds the hose nozzle out front for the hero photo."]}, "little-shark": {"m": ["Gray hoodie, 1 (buy: thrift store or closet)", "Gray felt, 1 sheet (buy: craft store; construction paper works too)", "White felt, 1 small sheet (buy: craft store; white paper works too)", "Fabric glue (buy: craft store)", "Scissors (make: household tools)"], "s": ["Buy the gray hoodie, gray felt, and white felt from the craft store. Gather the scissors and fabric glue.", "Cut a triangle fin about 8 inches tall from the gray felt. Cut a jagged row of teeth from the white felt.", "Glue the teeth inside the hood edge of the gray hoodie so they show around the face.", "Glue the fin to the back of the gray hoodie, low between the shoulders.", "Let the fabric glue dry flat for 30 minutes.", "Zip the gray hoodie over a white t-shirt and pull the hood up for the shark face."]}, "walking-taco": {"m": ["Tan vest or tan t-shirt (make: from closet)", "Brown, red, green, and yellow felt sheets, 1 pack (buy: craft store; construction paper works too)", "Fabric glue (buy: craft store)", "1 headband (buy: dollar store)", "Scissors (make: from home)"], "s": ["Buy the felt pack, fabric glue, and headband.", "Dress the kid in the tan vest or tan t-shirt.", "Safety: cut the felt slowly and keep fingers clear of the scissors.", "Glue two curved strips of brown felt down the front of the tan vest to form the shell fold.", "Make the toppings: cut wavy strips of green felt for lettuce and red circles for tomatoes. Cut yellow rectangles for cheese and brown blobs for beef. Glue them in a row across the chest and shoulders so they spill out like a taco filling.", "Make the headband garnish: glue one green felt strip and one red felt circle to the headband. Wear it with the vest as a lettuce and tomato topper."]}, "ramen-bowl": {"m": ["Large cardboard circle or shallow bowl shape, 1 (make: cut from a big box, about 2 feet wide)", "White and red paint for the bowl (buy: craft store)", "Yellow yarn, 1 skein (buy: craft store; yellow string works too)", "White craft foam or a foam ball, 1 (buy: craft store; white paper works too)", "Chopsticks, 1 pair (make: from the kitchen drawer)", "Tape and string (make: household tools)"], "s": ["Buy the white and red paint, yellow yarn, and white craft foam.", "Cut the cardboard circle into a wide bowl rim shape with the scissors. Paint it white with a red stripe and let it dry fully, about 1 hour.", "Make the noodles: cut dozens of 12-inch yellow yarn strands. Fasten them in a tangled layer across the top of the dry bowl rim with the tape.", "Cut the white craft foam into a half egg shape and paint a yellow yolk dot on it. Let it dry, then tape the egg on top of the noodles and stick the chopsticks in at an angle.", "Wear the bowl rim like a hat with string under the chin, noodles and egg on top. Slurp loudly for effect."]}, "tiny-snail": {"m": ["Neutral beige or tan clothes (make: from closet)", "1 large cardboard sheet or a flattened box (make: from home)", "Brown and tan markers or crayons (make: from home)", "2 backpack straps or 2 long ribbons (make: from home)", "1 headband (buy: dollar store)", "2 black pom-poms (buy: craft store; cotton balls work too)", "Tape (make: from home)"], "s": ["Dress the kid in the beige or tan clothes.", "Buy the headband and black pom-poms.", "Safety: cut the cardboard slowly and keep fingers clear of the scissors.", "Make the shell: cut the cardboard into a large oval. Draw a spiral from the center outward with the brown marker. Tape the two backpack straps to the back so it wears like a backpack.", "Make the eyestalks: tape two short cardboard strips to the headband so they point up. Tape a black pom-pom to the top of each strip.", "Wear the shell backpack and the headband with the pom-pom eyestalks. Keep the shell light and the straps snug so it rides comfortably."]}, "little-witch": {"m": ["Black cape or black bedsheet, 1 (buy: dollar store, or make: cut a cape from a black t-shirt)", "Pointy witch hat (buy: dollar store)", "Black-and-white striped tights (buy: thrift store or online)", "Green face paint (buy: drugstore or craft store)", "Safety pin or ribbon, 1 (make: from sewing kit)"], "s": ["Buy the pointy witch hat, black-and-white striped tights, and green face paint. Pull a black cape or black bedsheet from the closet.", "Pin the cape at the shoulders with the safety pin or tie it with ribbon.", "Paint the nose, chin, and forehead lightly green with a fingertip or sponge. Use non-toxic kids' green face paint only.", "Pull on the black-and-white striped tights and the pointy witch hat.", "Carry a branch from the yard as a broom if one is handy."]}, "spider": {"m": ["Black sweatshirt and black sweatpants (make: from closet)", "4 pairs of black socks (make: from the sock drawer)", "Newspaper or tissue paper for stuffing (make: from home)", "4 feet of thin black rope or black yarn (buy: craft store)", "Black fabric glue or a needle and black thread (buy: craft store)", "2 googly eyes, large (buy: craft store; drawn on paper circles work too)", "White face paint (buy: craft store or costume aisle)"], "s": ["Buy the black yarn, black fabric glue or black thread, googly eyes, and white face paint. Lay the black sweatshirt flat.", "Stuff each of the 8 socks about half full with crumpled newspaper or tissue. Leave the top half empty so each leg can bend.", "Use the black fabric glue or a few stitches to attach 4 stuffed socks down each side of the sweatshirt. Space them so they stick out like legs.", "Poke the black yarn through the middle of each stuffed sock and tie it for a knee bend. Glue one googly eye on each shoulder of the sweatshirt. Dress in the black sweatshirt and black sweatpants, then put on the leg-covered sweatshirt.", "Safety: use non-toxic face paint, and keep the googly eyes on the shoulders, not near the face.", "Dot the white face paint around the eyes as spider markings."]}, "backyard-hero": {"m": ["Old pillowcase or t-shirt for the cape (make: cut up)", "Solid-color t-shirt to wear (own)", "Cardstock or foam letter for the first initial (make: cut from cardstock, or buy: craft store)", "Ribbon or string for cape ties (own, or buy: craft store)", "Safety pins", "Scissors"], "s": ["Cut the cape from the old pillowcase with the scissors. Slit one seam open and trim it to waist length.", "Cut the first initial from the cardstock with the scissors. Pin it to the chest of the solid-color t-shirt with a safety pin.", "Safety: keep the neck bow loose and easy to pull free. Never tie anything tight around the neck.", "Thread the ribbon through the top corners of the cape. Tie it at the front of the neck in a loose quick-release bow. Trim the ribbon ends with the scissors."]}, "pickle": {"m": ["Green tunic or oversized green t-shirt, 1 (buy: thrift store or closet)", "Green bubble wrap or green pom-poms, about 20 (buy: craft store, or make: twist bits of green fabric)", "Fabric glue (buy: craft store)", "Green face paint (buy: drugstore)"], "s": ["Buy the green tunic, green bubble wrap, and green face paint. Glue the bubble wrap bumps or green pom-poms all over the front and back of the green tunic. This makes the bumpy pickle texture.", "Let the fabric glue dry flat for 30 minutes.", "Paint the face with the green face paint, then draw on a smug grin with one raised eyebrow.", "Wear the green tunic over regular clothes and stand tall."]}, "vampire": {"m": ["Black cape or black bedsheet (buy cape: costume aisle; or make: from a black sheet from home)", "Black shirt and pants (make: from closet)", "Plastic vampire fangs (buy: costume aisle or dollar store)", "Hair gel or pomade (make: from home)", "Red lipstick or red face paint (buy: pharmacy or costume aisle)", "White face powder or pale face paint (buy: costume aisle)"], "s": ["Buy the black cape, vampire fangs, pale face paint, and red lipstick if needed.", "Dress in the black shirt and pants.", "Make the hair: work the hair gel through the hair with your fingers. Press it straight back until it sits flat and slick.", "Safety: use non-toxic costume makeup, and skip the vampire fangs for small kids who might choke on them.", "Make the face: dust the pale face paint over the face and neck. Dab a thin line of red lipstick at each corner of the mouth like drips of blood.", "Wear the black cape over the shoulders and pop the vampire fangs in last before photos."]}, "bamboo-demon": {"m": ["Pink bathrobe or kimono-style robe (own, or buy: clothing store)", "Long dark wig (buy: toy store or online)", "1 cardboard tube from wrapping paper or paper towels (make: save from home)", "Ribbon or string (own, or buy: craft store)", "Red non-toxic face paint (buy: toy store)", "Scissors", "Tape"], "s": ["Buy the long dark wig, ribbon, and red non-toxic face paint.", "Cut the cardboard tube to chin width with the scissors. Tape a length of ribbon to each end of the tube.", "Safety: keep the knot loose enough to talk and breathe easily. Never tie anything tight around the head or neck.", "Tie the cardboard tube across the mouth with the ribbon, knotting loosely at the back of the head.", "Pull on the pink bathrobe. Put on the long dark wig.", "Dab a small red mouth mark on the cardboard tube with the red non-toxic face paint."]}, "emoji-crew": {"m": ["1 yellow t-shirt per person (buy: craft store or use one you own)", "1 large white paper plate or cardboard circle per person (make: use what you own)", "Markers in black, red, blue (make: use what you own)", "Scissors, tape"], "s": ["Buy yellow t-shirts if the crew does not own them.", "Safety: adults handle the scissors when cutting the paper plates or cardboard circles.", "Each person picks an emoji, trims the plate or cardboard circle if needed, and draws it big with the markers.", "Tape the paper plate to the chest of the yellow t-shirt, centered like a face.", "Gather the crew in a row for photos, keeping the paper plates taped flat so they do not swing."]}, "robot-crew": {"m": ["1 medium cardboard box per person, big enough to fit over the torso (make: from home or moving boxes)", "1 small cardboard box per person, for the head (make: from cereal or shoe boxes)", "Aluminum foil, 1 large roll (buy: grocery store)", "Plastic bottle caps, about 20 total (make: save from drinks)", "Duct tape, 1 roll (buy: hardware store)", "Black permanent marker, 1 (make: from home)", "Elastic string or yarn, 6 ft (buy: craft store)", "Glow sticks, 1 per person (buy: dollar store)"], "s": ["Buy the aluminum foil, duct tape, glow sticks, and elastic string.", "Safety: cut the cardboard boxes slowly and keep fingers clear of the scissors. Keep the eye holes big enough to see clearly, and use duct tape instead of sharp wire near the face.", "Cut head and arm holes in each medium cardboard box so they slide over the torso. Cut eye holes in the small cardboard boxes for heads.", "Wrap every box in aluminum foil, taping the foil down with duct tape. Draw dials and gauges on the chest with the black permanent marker. Tape the plastic bottle caps next to the dials as buttons.", "Wrap leftover aluminum foil around each arm from wrist to shoulder and tape the ends with duct tape. Or cut the armholes in the torso box big enough to slide bare arms through.", "Each person slides into a torso box and holds or ties the small cardboard box on their head. Tie the elastic string under the chin to keep the head box on. Crack a glow stick and tape it to the chest as a power light."]}, "cereal-crew": {"m": ["Solid-color shirt and pants per person (own)", "Empty cereal boxes, 1 per person (make: save from home)", "Markers or crayons (own)", "String (own)", "Scissors", "Tape"], "s": ["Each person invents a cereal name.", "Cut the front panel off an empty cereal box with the scissors.", "Decorate the panel with the markers or crayons. Draw a mascot, add a prize burst, and write the cereal name in big letters.", "Tape string to the top corners of each panel with the tape.", "Wear the panel over the solid-color shirt like a sandwich board."]}, "decades-crew": {"m": ["Each person's own closet clothes (make: use what you own)", "1 printed decade card per person, e.g. 70s, 80s, 90s (make: hand-letter on paper)", "Scissors", "Tape or safety pins", "Hair gel or spray (buy: drugstore)"], "s": ["Everyone digs through their closet clothes and picks a different decade.", "Safety: adults handle the scissors when trimming the decade cards.", "Hand-letter a decade card on paper, like '80s, and tape it to each chest.", "Build each look with closet props only: bell-bottoms and a headband for the 70s. Neon and high socks for the 80s. Flannel tied at the waist for the 90s.", "Style hair with hair gel to sell the decade: a big part for the 70s. A scrunchie side-ponytail for the 80s.", "Keep props light so the looks survive a whole night of walking."]}, "under-the-sea": {"m": ["Jellyfish: 1 clear umbrella and pastel ribbons (buy umbrella: dollar store; buy ribbons: craft store; crepe paper strips work too)", "Crab: red shirt and pants plus red mittens or red socks for hands (make: from closet)", "Fish: silver or blue clothes and 1 large cardboard fish cutout (make: from home)", "Seaweed: green clothes and long green streamers (buy: party store)", "Waves: blue sheet or blue blanket to drape (make: from home)", "Tape and scissors (make: from home)"], "s": ["Assign one sea creature per person. Buy the clear umbrella, pastel ribbons, and green streamers. Pull the colored clothes from closets.", "Safety: cut the ribbons slowly and keep fingers clear of the scissors. Hold the clear umbrella high and keep the tentacle ribbons clear of faces.", "Jellyfish: cut the pastel ribbons into 3-foot lengths. Tape them to the edge of the clear umbrella so they dangle like tentacles. Hold the clear umbrella overhead.", "Crab: dress in red and slide the red mittens or red socks onto the hands. Hold both hands up with fingers pinched like claws. Fish: tape the cardboard fish cutout to the chest over the silver clothes.", "Seaweed: tape the green streamers to the shoulders and arms so they wave when the arms move. Everyone together can hold the blue sheet behind the group as a wave backdrop for the photo."]}, "dino-rangers": {"m": ["Grown-ups: khaki shirt and pants from your closet (make: use what you own)", "Kids: green hoodie per child (buy: thrift store or use one you own)", "White paper or card for the eye spots (make: use what you own)", "1 toy dinosaur or plush per kid (buy: toy store)", "1 short ribbon or string leash (make: use what you own)", "Tape, scissors"], "s": ["Dress the grown-ups in the khaki shirt and pants, and roll the sleeves for the field-guide look.", "Buy or dig out the green hoodie for each kid, the toy dinosaur, and the ribbon.", "Safety: adults handle the scissors when cutting the white paper.", "Cut two eye spots from the white paper, and tape them to the hood of the green hoodie.", "Safety: skip small plastic dinosaur toys for kids under three, since they are a choking hazard.", "Loop the ribbon around the toy dinosaur like a leash, and tie the other end to the kid's wrist. Keep the leash short so the toy dinosaur does not drag."]}, "board-game-pieces": {"m": ["Black or white monochrome clothes (own)", "Large cardboard boxes (make: collect spares)", "White and black acrylic paint (buy: craft store, tempera paint works too)", "Paintbrushes", "Black marker (buy: dollar store)", "Ribbon or string for straps (own)", "Scissors", "Tape"], "s": ["Each person picks a game piece to be.", "Cut a cube shape from a large cardboard box for the die with the scissors. Cut flat boards from another box for the playing card and the domino.", "Paint the die and card white and the domino black with the acrylic paint and paintbrushes. Let the paint dry fully.", "Add dots and card symbols with the black marker and the white acrylic paint once the base coats are dry.", "Safety: cut the die box eye holes generously so you can see clearly. Only wear the die box once all paint is fully dry.", "Tape ribbon straps to the flat boards so they hang front and back over the black or white monochrome clothes. Wear the die box over the head with the eye holes lined up."]}, "rain-cloud-rainbow": {"m": ["Gray t-shirt or sweatshirt (buy: thrift store or closet)", "White cotton balls or polyester stuffing, 1 bag (buy: dollar store or craft store)", "Blue paper raindrops, about 15 (make: cut from blue construction paper)", "String and tape (make: household tools)", "Fabric glue (buy: craft store)", "Rainbow-striped shirt or a white shirt plus rainbow fabric markers (buy: thrift store or craft store)", "Blue face paint for one rain streak (buy: drugstore, optional)"], "s": ["Buy the gray t-shirt, white cotton balls, fabric glue, and rainbow-striped shirt or rainbow fabric markers.", "Glue the white cotton balls in clumps across the gray t-shirt to make clouds.", "Fix the blue paper raindrops to short pieces of string with tape. Hang the strings from the bottom edge of the gray t-shirt so they dangle.", "The rainbow person: wear the rainbow-striped shirt, or draw rainbow arcs across a white shirt with the rainbow fabric markers.", "Stand side by side: the cloud holds arms out wide. The rainbow stands just behind, peeking out after the 'storm'. Add one blue rain streak on a cheek with the blue face paint if you like."]}, "doctor-bride": {"m": ["The Doctor: old dark suit or jacket from your closet (make: use what you own)", "The Doctor: green face paint, non-toxic (buy: drugstore)", "The Doctor: 2 plastic bolts, e.g. costume bolts (buy: craft store; foil-covered cardboard tubes work too)", "The Bride: white dress or old white sheet (make: use what you own)", "The Bride: white hair spray (buy: drugstore)", "Tape or glue", "Scissors", "Dark eye shadow (make: use what you own)"], "s": ["Buy the green face paint, plastic bolts, and white hair spray.", "Safety: keep face paint away from the eyes, and patch-test it first on sensitive skin. Wash it off the same night.", "The Doctor: paint the face and neck green with the green face paint.", "Tape the two plastic bolts to the sides of the neck, and wear the dark suit with the collar up.", "The Bride: tear the bottom hem of the white dress or sheet into strips. Spray the hair white with the white hair spray.", "Smudge dark eye shadow under the eyes."]}, "breakfast-buffet": {"m": ["Cardboard sheets, 1 per person (make: cut from boxes)", "Markers (own, or buy: dollar store)", "String or yarn (own)", "Scissors"], "s": ["Each person picks a breakfast item.", "Cut a large circle or rectangle from the cardboard sheets with the scissors.", "Draw the food big on the cardboard with the markers. Draw a fried egg, bacon strips, buttered toast, a pancake stack, a glass of OJ, or a coffee mug.", "Safety: an adult pokes the holes in the top corners with the tip of the scissors, since pushing through cardboard takes force.", "Thread the string through the holes and wear the sign over normal clothes like a sandwich board."]}, "ghost-hunters": {"m": ["1 khaki or tan jumpsuit or matching shirt and pants per person (buy: thrift store)", "1 small cardboard box per person (make: use what you own)", "White paper and markers for name patches (make: use what you own)", "1 sheet black cardboard per person (make: from a box)", "Packing tape or glue, scissors"], "s": ["Buy the khaki jumpsuit or matching shirt and pants for each person.", "Tape the small cardboard box shut for the backpack.", "Safety: adults handle the scissors when cutting the black cardboard.", "Cut two straps, one dial, and one hose shape from the black cardboard, and tape them to the box.", "Mark each last name on the white paper with the markers. Tape it to the chest as a name patch.", "Wear the backpack over the jumpsuit, and keep the box small and light so kids can wear it all night."]}, "haunted-animatronics": {"m": ["1 large cardboard box per person, big enough to cover the head (make: use what you own)", "2 red LED tea lights per person (buy: dollar store)", "Paint in gray, black, and one accent color (buy: craft store)", "Old clothes with holes or tears (make: use what you own)", "Hot glue, scissors, a utility knife (adults only)"], "s": ["Buy the red LED tea lights and the paint. Pull the old clothes with holes and the large cardboard boxes from home.", "Safety: an adult handles the utility knife and the hot glue for every cut and glue step.", "Cut eye holes and a wide jagged mouth from each box with the utility knife.", "Paint the box gray with black scuffs and cracks. Glue one red LED tea light inside each eye hole.", "Safety: make the eye holes large, and never wear the box near stairs or traffic, since side vision is limited.", "Wear the box over the head with the eyes lined up to the holes. Wear the old clothes with holes underneath, and move in short jerky steps, freezing between moves."]}, "mystery-crew": {"m": ["Orange, purple, blue, and red t-shirts, 1 each (buy: thrift store or closet)", "Dog ears headband or a brown dog costume piece (buy: dollar store)", "Fake magnifying glass (buy: dollar store, or make: a paper circle taped to a stick)", "Headband or scarf in a matching color, 1 per person (make: from the drawer)", "Brown face paint for the dog's nose (buy: drugstore)"], "s": ["Buy the dog ears headband and the fake magnifying glass.", "Assign roles: orange leader, purple style icon, blue brains, red goofball, and the dog wears the ears.", "Each person: put on their color's t-shirt and tie a matching headband or scarf.", "The brains carries the fake magnifying glass. Paint a brown nose on the dog with the brown face paint.", "Group the four humans in a line with the dog in front. All point at something suspicious for the classic pose."]}, "headless-horsemen": {"m": ["Each person: 1 black cape or black sheet (buy: dollar store or use a black sheet)", "Each person: 1 small jack-o-lantern bucket or foam pumpkin (buy: dollar store)", "Each person: 1 broom or stick horse substitute (make: use a broom from home)", "Tape", "Glow bracelets (buy: dollar store)"], "s": ["Buy the black cape, the jack-o-lantern bucket, and the glow bracelets.", "Drape the black cape or black sheet over the shoulders.", "Safety: keep your real head tucked low so you can see the ground.", "Tuck the chin into the chest, and hold the jack-o-lantern bucket up at shoulder height like a carried head.", "Add a glow bracelet to each wrist so drivers can see you in the dark.", "Hold the broom between the legs like a horse, and gallop in a group line."]}, "haunted-portraits": {"m": ["Each person: old-fashioned dark clothes, e.g. a vest, long skirt, or button-up (make: use your closet)", "Gray and white face paint, non-toxic (buy: drugstore)", "1 large picture frame or cardboard frame per person (buy: thrift store for the frame, or make from cardboard)", "Hair spray or powder for a grayed look (buy: drugstore)"], "s": ["Buy the gray and white face paint and the hair powder.", "Paint each face pale gray with white highlights on the cheekbones and nose, using the gray and white face paint.", "Gray the hair with the hair powder.", "Dress in the old-fashioned dark clothes from the closet.", "Hold the picture frame or cardboard frame up around the face like a living portrait.", "Pose together in a row of frames for group photos, keeping the face paint light around the eyes."]}, "goggle-crew": {"m": ["1 yellow t-shirt per person (buy: craft store or use one you own)", "1 pair denim overalls per person (buy: thrift store or use one you own)", "1 pair swim or safety goggles per person (buy: toy store)", "1 pair black gloves per person (buy: dollar store)"], "s": ["Buy the yellow t-shirts, denim overalls, goggles, and black gloves.", "Each person puts on the yellow t-shirt, the denim overalls, and the black gloves.", "Push the goggles up on the forehead like safety gear, not over the eyes, so everyone can see.", "Walk in a pack and greet people in gibberish for the full effect.", "Skip any real tools or hard hats so the look stays clearly costume, not work gear."]}, "garden-gnome": {"m": ["Earth-tone shirt and pants (make: use your closet)", "1 sheet cardboard for the hat (make: from a box)", "Blue paint for the hat (buy: craft store)", "White face paint for the beard, non-toxic (buy: drugstore)", "1 toy fishing rod or small garden shovel (buy: dollar store)", "Scissors, tape"], "s": ["Buy the blue paint, the white face paint, and the toy fishing rod.", "Safety: adults handle the scissors when cutting the cardboard.", "Cut the sheet cardboard to size, roll it into a tall cone, and tape it shut.", "Paint the cone with the blue paint for the hat, and let it dry.", "Paint a white beard across the lower cheeks and chin with the white face paint, keeping it below the mouth.", "Wear the cone hat with the earth-tone shirt and pants, and carry the toy fishing rod."]}, "black-cat": {"m": ["Black shirt and pants or sweatsuit (own)", "Plain headband (buy: dollar store)", "1 sheet black craft felt (buy: craft store, construction paper works too)", "Black construction paper (make: cut a mask from it)", "Black non-toxic face paint (buy: toy store)", "Small drawstring bag or pillowcase (own)", "Scissors", "Tape"], "s": ["Buy the plain headband, black craft felt, and black non-toxic face paint.", "Cut two triangle ears from the black craft felt with the scissors. Cut one eye mask shape from the black construction paper.", "Tape the ears upright to the plain headband.", "Safety: cut the eye holes wide in the mask so vision stays clear.", "Tape the mask on with long tape tabs at the temples. Or draw whiskers with the black non-toxic face paint.", "Pull on the black shirt and pants and put on the plain headband. Carry the small drawstring bag over one shoulder."]}, "block-monster": {"m": ["Solid-color sweatsuit, any color (own)", "1 large cardboard box (make: cut it into square blocks)", "Packing tape", "Scissors", "Non-toxic face paint (buy: toy store)"], "s": ["Cut the large cardboard box into square blocks with the scissors: two large, four medium.", "Tape one large block to each shoulder with the packing tape.", "Tape one medium block to each forearm and shin with the packing tape.", "Pull on the solid-color sweatsuit under the blocks.", "Safety: keep the face paint clear of the eyes.", "Draw a blocky square-toothed grin on the face with the non-toxic face paint."]}, "space-crewmate": {"m": ["Plain sweatsuit in one solid color, red recommended (make: from closet)", "Cardboard, 1 sheet about 12x16 inches (make: from a box flap)", "Aluminum foil, enough to cover the cardboard (make: from the kitchen)", "2 backpack straps or 2 long shoelaces (make: from home)", "Markers, several colors (make: from home)", "Tape (make: from home)"], "s": ["Dress in the solid-color sweatsuit.", "If you have more than one person, give each a different color.", "Wrap the cardboard in aluminum foil for the backpack. Draw vents, dials, and one big red button with the markers. Tape the two backpack straps to the back of the cardboard.", "Wear the foil backpack with the straps over your shoulders. Tape the bottom corners snug to the sweatsuit so it does not swing.", "Finishing touch: hold one finger to your lips and say sus for the photo."]}, "sun-moon": {"m": ["Yellow shirt and pants for the Sun (make: from closet)", "Navy or black shirt and pants for the Moon (make: from closet)", "Yellow cardstock, 2 sheets (buy: craft store; construction paper works too)", "Silver star stickers, 1 sheet (buy: craft store; cut paper stars work too)", "White and yellow paper for the crescent (make: from home)", "Tape and scissors (make: from home)"], "s": ["One person dresses head to toe in yellow, the other in navy or black.", "Buy the yellow cardstock and the silver star stickers.", "Safety: cut the cardstock slowly and keep fingers clear of the scissors.", "Make the sun rays: cut 10 long triangles from the yellow cardstock. Tape them around the neckline and sleeves of the yellow shirt so they point outward.", "Cut a large crescent from the white paper and tape it to the chest of the navy shirt. Scatter the silver star stickers across the shirt and arms.", "Finishing touch: the Sun spreads arms wide to show the rays while the Moon holds one hand near the crescent."]}, "moth-porch-light": {"m": ["Neutral shirt and pants in gray, brown, or tan (make: from closet)", "Large cardboard box, 1 (make: cut two wing shapes from it)", "Brown and tan markers or paint (buy: craft store)", "Brown craft pipe cleaners, 2 (buy: craft store; brown yarn works too)", "Headband, 1 (make: from the drawer)", "Yellow t-shirt and yellow pants (buy: thrift store or closet)", "Cone lampshade, 1 (buy: thrift store)", "Tape and scissors (make: household tools)"], "s": ["Buy the brown craft pipe cleaners, brown and tan markers, and cone lampshade. Cut two large oval wing shapes from the large cardboard box with the scissors.", "Draw eye spots and scalloped edges on the wings with the brown markers. Tape one wing to each arm of the neutral shirt and pants.", "Bend the brown craft pipe cleaners into feathery antennae and tape them to the headband for the moth.", "Put on the yellow t-shirt and yellow pants. Pop the cone lampshade over the head like a lampshade hat.", "Stand next to the moth with arms out, buzzing."]}, "raptor-ranger": {"m": ["Khaki shirt and hat for the ranger (make: from closet, or buy at a thrift store)", "Green hoodie or green t-shirt for the raptor (make: from closet)", "Green felt sheet for the tail (make: cut and tape; construction paper works too)", "3 ft rope or a toy dog leash (buy: pet aisle)", "Face paint, green and black (buy: costume aisle or craft store)"], "s": ["Decide who is the ranger and who is the raptor, then lay out both outfits. Buy the 3 ft rope or toy dog leash and the face paint if you do not have them.", "Safety: cut the green felt sheet slowly and keep fingers clear of the scissors.", "Cut a long triangle from the green felt sheet for the tail. Tape it to the back of the raptor's green shirt so it hangs behind them.", "The ranger wears the khaki shirt and hat with the toy dog leash in hand. The raptor wears the green shirt with the tail attached.", "Safety: use non-toxic kids face paint, and skip any mask so the raptor can see clearly.", "Paint the raptor's snout: use the green face paint to draw a snout and two black dots for nostrils. Then the ranger holds the toy dog leash out toward the raptor for photos."]}, "cat-mouse": {"m": ["2 headbands (buy: dollar store)", "1 sheet black craft felt (buy: craft store, construction paper works too)", "1 sheet gray craft felt (buy: craft store, construction paper works too)", "Black eyeliner pencil or non-toxic face paint (buy: toy store)", "Scissors", "Tape"], "s": ["Buy the headbands, black craft felt, gray craft felt, and black eyeliner pencil.", "Cut two triangle ears from the black craft felt with the scissors. Cut two round ears from the gray craft felt.", "Tape the triangle ears to one headband for the cat. Tape the round ears to the other headband for the mouse.", "Safety: keep the eyeliner clear of the eyes.", "Put on the headbands and draw whiskers on both faces with the black eyeliner pencil."]}, "ketchup-mustard": {"m": ["Ketchup: 1 red tunic or oversized red t-shirt (buy: craft store)", "Mustard: 1 yellow tunic or oversized yellow t-shirt (buy: craft store)", "2 white paper plates for the caps (make: use what you own)", "White fabric paint for the labels (buy: craft store)", "Tape, scissors"], "s": ["Buy the red tunic, the yellow tunic, and the white fabric paint.", "Paint your label word, 'Ketchup' or 'Mustard', in big letters across the chest with the white fabric paint.", "Let the white fabric paint dry fully before wearing.", "Safety: adults handle the scissors when cutting the white paper plates.", "Cut a bottle-cap shape from each white paper plate, and tape one to the top of each head. Use painter's tape so it does not pull hair.", "Stand side by side for the full condiment effect."]}, "plumber-duo": {"m": ["Blue overalls, 2 (buy: thrift store)", "Red t-shirt and green t-shirt, 1 each (buy: thrift store or closet)", "Red cap and green cap, 1 each (buy: dollar store)", "Brown face paint for mustaches (buy: drugstore)", "White circle stickers or white paper, 2 (buy: dollar store)", "Marker (make: household)"], "s": ["Buy the blue overalls, red cap, green cap, white circle stickers, and brown face paint. Pull the red t-shirt and green t-shirt from the closet.", "Write a big 'M' on one white circle and an 'L' on the other with the marker. Stick or tape them to the front of the red cap and green cap.", "Each brother: wear the blue overalls over their colored t-shirt and cap. Paint on a mustache with the brown face paint. The red brother gets a big bushy one, and the green brother gets a thinner one.", "Roll the overall cuffs once and strike the jump pose with a fist in the air. Talk about fixing pipes all night."]}, "office-couple": {"m": ["White button-down shirts, 2 (make: from closet)", "Name tags, 2 (buy: office supply store, or make: index cards with safety pins)", "Toy teapot or a small real teapot (make: from the kitchen)", "Black pants or skirts, 2 (make: from closet)", "Marker for writing names (make: household)"], "s": ["Buy name tags, or make them from index cards and safety pins. Pull the white button-down shirts and black pants or skirts from the closet.", "Write joke job titles on the name tags with the marker and pin them on the white button-down shirts.", "One person carries the toy teapot proudly all evening. The other carries a clipboard or a stack of papers.", "Tuck the white button-down shirts in and straighten each other's collars. Introduce yourselves by your fake titles to everyone you meet."]}, "burger-joint-couple": {"m": ["2 white aprons (buy: dollar store or online)", "Fake mustache (buy: toy store)", "Curly red wig (buy: toy store or online)", "Costume glasses (buy: toy store)", "Order pad and pencil (own, or buy: dollar store)"], "s": ["Buy the white aprons, fake mustache, curly red wig, costume glasses, and order pad.", "One partner pulls on a white apron and sticks on the fake mustache with its skin-safe adhesive.", "The other partner pulls on the second white apron, the curly red wig, and the costume glasses.", "Carry the order pad and pencil and take each other's burger orders all night.", "Remove the fake mustache gently at the end of the night."]}, "plug-socket": {"m": ["Cardboard box, 1 large (make: cut two flat panels, one per person)", "Gray and white acrylic paint (buy: craft store)", "Black markers (make: household)", "Craft foam, 1 sheet (buy: craft store; cardboard works too)", "Tape and string for wearing (make: household tools)", "Scissors (make: household tools)"], "s": ["Buy the gray and white acrylic paint and the craft foam. Cut two cardboard panels from the large cardboard box with the scissors, each about 2 feet square, one per person.", "Make the plug: paint one panel gray. Draw two prongs on the craft foam, cut them out, and tape them sticking up from the top edge.", "Make the socket: paint the other panel white. Draw two dark slots and a round outlet face with the black markers.", "Fix the string to the back corners of each panel with tape so they hang like sandwich boards. The plug person stands next to the socket person."]}, "lost-tourist": {"m": ["Wrinkled button-down shirt (make: from closet, slept on or stuffed in a bag)", "Tourist accessories: sunglasses, camera or phone on a strap (make: from around the house)", "Paper map, 1 (buy: print one at home, or make: draw a fake map on printer paper and crumple it)", "Luggage tag, 1 (buy: office supply store, or make: an index card with a string)", "Clear tape (make: household tools)"], "s": ["Wrinkle the button-down shirt on purpose. Stuff it in a bag overnight, or ball it up and sit on it for ten minutes.", "Write a fake name and hometown on an index card for the luggage tag. Punch a hole in the card and tie on the string.", "Tape the luggage tag backwards on one shoulder with the clear tape so it faces the wrong way.", "Crumple the paper map into a ball, flatten it once, and carry it unfolded the wrong way up.", "Hang the camera or phone around the neck and put the sunglasses on top of the head.", "Walk around looking at the map upside down."]}, "tooth-fairy": {"m": ["Tooth: all-white outfit (make: from closet)", "Tooth fairy: white dress or white shirt with a white skirt (make: from closet)", "White cardstock, 1 large sheet (buy: craft store)", "White felt wings or a wire coat hanger with white pantyhose (buy: craft store, or make: from home)", "1 small envelope and play money or a coin (make: from home)", "Glitter glue, 1 tube (buy: craft store)", "1 stick and aluminum foil for the wand (make: from home)", "Tape and scissors (make: from home)"], "s": ["Buy the white cardstock, glitter glue, and felt wings if you are not making them.", "Pull the white clothes from the closet.", "Make the tooth: cut a large tooth shape with two roots from the white cardstock. Edge it with the glitter glue and let it dry. Tape it to the chest of the white outfit.", "Safety: tape down any sharp wire ends from the wire coat hanger, and keep fingers clear of the scissors.", "Make the wings: stretch the white pantyhose over a reshaped wire coat hanger to form two wing loops. Tape the hanger ends to a piece of cardboard worn at the back. Tuck the envelope with play money into a pocket or waistband.", "Tooth fairy: wear the white dress and strap on the wings. Carry the wand made from the stick with an aluminum foil star taped on top."]}, "web-hero-duo": {"m": ["Hero: red and blue sweatsuit or red shirt with blue pants (make: from closet)", "Partner: black jacket and black pants (make: from closet)", "Black face paint or a black eye mask (buy: costume aisle)", "White face paint or white stickers (buy: craft store)", "Red web gloves or red socks for hands (make: from closet)", "Tape (make: from home)"], "s": ["Buy the black face paint or black eye mask, and the white stickers.", "Pull the red and blue outfit and the black jacket and black pants from closets.", "Safety: use non-toxic face paint, and keep paint out of the eyes.", "Hero: paint a black eye mask with the black face paint across the eyes. Add white web lines over the red shirt using the white face paint. Or tear thin strips of tape in a web pattern over the shirt. Pull the red socks onto the hands as web gloves.", "Partner: wear the black jacket and black pants and slick the hair back. Strike the brooding pose. No crafting needed beyond the outfit.", "Finishing touch: the hero throws one arm out in a web-shooting pose while the partner crosses their arms behind them."]}, "plague-doctor": {"m": ["Long black coat or black robe, 1 (buy: thrift store)", "Wide-brim black hat (buy: dollar store)", "Black half mask or sunglasses (buy: dollar store)", "Cardboard or craft foam for the beak, 1 sheet (buy: craft store; stiff paper works too)", "Black gloves, 1 pair (buy: dollar store)", "Hot glue gun (buy: craft store)", "Black spray paint or black markers (buy: craft store)"], "s": ["Buy the long black coat, wide-brim black hat, black half mask, black gloves, hot glue gun, and beak materials. Cut a long curved beak shape from the cardboard or craft foam.", "Safety: let an adult handle the hot glue gun, and keep fingers away from the nozzle.", "Paint the beak black with the black spray paint and let it dry. Hot-glue the beak to the front of the black half mask so it juts out.", "Safety: fit the black half mask so the eyes are fully open. Never wear a mask that blocks peripheral vision.", "Cut round eye holes in the black half mask and fit it so the eyes are fully open.", "Wear the long black coat, wide-brim black hat, black gloves, and the beaked mask together. Carry a wooden staff or walking stick for the full effect."]}, "crowd-camouflage": {"m": ["Gray hoodie (own)", "Dark pants (own)", "Gray beanie (own, or buy: dollar store)", "Blank adhesive name tag (buy: dollar store)", "Pen (own)"], "s": ["Pull on the gray hoodie with the hood up, the dark pants, and the gray beanie.", "Leave the blank adhesive name tag blank. Write nothing on it with the pen and stick it to the chest of the gray hoodie.", "Keep a blank expression, hood up, and blend into the background of every group photo."]}, "error-404": {"m": ["Black t-shirt and black pants (make: use your closet)", "White fabric paint or white paper (buy: craft store)", "Old phone case or a cracked-screen phone protector prop (make: use an old case)", "Scissors", "Tape (make: use what you own)"], "s": ["Buy the white fabric paint. Dig the black t-shirt, black pants, and old phone case out of the closet.", "Paint or stencil the words 'Page Not Found' across the chest of the black t-shirt.", "Use the white fabric paint or white paper for the letters, and let the paint dry fully.", "Tape the old phone case to one hand.", "Walk around staring at the old phone case, announcing that the page cannot be found."]}, "zombie-coworker": {"m": ["Old button-down shirt you can cut up (make: from closet)", "Old tie (make: from closet)", "Pale face paint or white face powder (buy: costume aisle)", "Dark eye makeup or black eyeshadow (buy: pharmacy)", "Coffee mug (make: from home)", "Scissors (make: from home)"], "s": ["Buy the pale face paint and dark eye makeup.", "Pull the old button-down shirt, old tie, and coffee mug from home.", "Safety: cut away from your fingers, and keep the scissors away from small kids. Use non-toxic costume makeup.", "Make the torn shirt: cut jagged slits along the hem of the old button-down shirt and one sleeve. Tie the old tie loosely and crookedly around the neck.", "Make the face: cover the face with the pale face paint. Ring the eyes with the dark eye makeup. Smudge a little down one cheek like a long night at the office.", "Wear the torn shirt with the loosened tie and carry the coffee mug everywhere, mumbling about the quarterly review."]}, "the-olympians": {"m": ["White bedsheets or large white fabric, 1 per person (make: raid the linen closet)", "Gold rope or gold cord, 2 yards per person (buy: craft store)", "Gold paper or gold craft leaves for laurel crowns (buy: craft store; gold paper works too)", "Gold face paint or gold eyeliner (buy: drugstore)", "Cardboard for the props: lightning bolt, trident, owl (make: from boxes)", "Gold markers or gold paint pen (buy: craft store)", "Safety pins, scissors, tape"], "s": ["Buy the gold rope, gold paper, gold face paint, and gold markers. Pull the white bedsheets from the linen closet.", "Make the togas: wrap one sheet around each person over a plain t-shirt and shorts, pinning at the shoulder with a safety pin. Belt it with the gold rope.", "Safety: pin from the outside of the fabric so pin backs face the clothes, never the skin. Keep the toga above the ankles so nobody trips.", "Make the laurel crowns: cut leaf shapes from the gold paper and tape them along a paper strip sized to each head.", "Make the god props: cut a lightning bolt, a trident, and an owl from the cardboard. Color them gold with the markers.", "Paint one gold detail on each face: a lightning streak, an owl feather, or a wave. Each god picks a power pose for the group photo."]}, "safari-photographer": {"m": ["Khaki vest with pockets (buy: thrift store, or make: wear a tan button-down from closet)", "Khaki pants or shorts (make: from closet)", "Toy camera (buy: dollar store, or make: draw a camera on cardboard and tape a strap)", "Toy binoculars (buy: dollar store; two paper towel rolls taped together work too)", "Stuffed lion or lion cub toy (buy: thrift store or toy aisle)", "Safari hat (buy: costume aisle, or make: wear any wide-brim hat from home)"], "s": ["Buy or gather the toy camera, toy binoculars, stuffed lion or lion cub toy, and safari hat.", "Pull the khaki pants and khaki vest from the closet.", "Safety: cut the cardboard slowly and keep fingers clear of the scissors.", "To make the camera: cut a camera shape from cardboard and draw a lens with a marker. Tape a ribbon or belt through it as a strap.", "Dress in the khaki pants, khaki vest, and safari hat. Hang the toy camera around your neck and the toy binoculars over the shoulder.", "Finishing touch: tuck the stuffed lion under one arm and practice your best explorer pose."]}, "player-one-two": {"m": ["Matching t-shirts, 2, any color (buy: thrift store or closet)", "Iron-on letters or fabric markers, spelling 1 and 2 (buy: craft store)", "Toy game controllers, 2 (buy: toy store, or make: draw one on cardboard)", "Iron (make: household)"], "s": ["Buy the matching t-shirts, iron-on letters or fabric markers, and toy game controllers.", "Put a big '1' on the front and back of one t-shirt with the iron-on letters. Put a big '2' on the front and back of the other t-shirt.", "Safety: let an adult handle the hot iron on a hard surface.", "Iron the letters onto the t-shirts, or draw them with the fabric markers.", "Each player: wear their numbered t-shirt and carry a toy game controller.", "Walk in together, controllers up, and argue good-naturedly all evening about who is really player one."]}, "dinosaur-family": {"m": ["1 green sweatsuit per person (buy: discount store or use one you own)", "1 sheet green felt per person (buy: craft store; construction paper works too)", "Scissors", "Fabric glue or safety pins", "Green face paint, non-toxic (buy: drugstore)"], "s": ["Buy one green sweatsuit and one sheet of green felt per person.", "Safety: adults handle the scissors when cutting the green felt.", "Cut green felt triangles about the size of your palm.", "Glue or pin the green felt triangles in a row from the hood down the back of the green sweatsuit.", "Paint green spots on each cheek with the green face paint, keeping it clear of the eyes.", "Put the green sweatsuit on over regular clothes, and pin the spikes flat to the hood so they stay put."]}, "snow-sisters": {"m": ["Ice queen: icy-blue dress or blue dress plus silver glitter glue (buy glitter glue: craft store)", "Snow princess: pink or lavender dress (make: from closet)", "Snowman: white shirt, white pants, 3 large black felt circles (buy felt: craft store; construction paper works too)", "Reindeer: brown clothes, 2 brown pipe cleaners, 1 red pom-pom (buy pipe cleaners and pom-pom: craft store)", "Silver headband (buy: dollar store)", "Tape and scissors (make: from home)"], "s": ["Assign roles, then buy the silver glitter glue, black felt circles, brown pipe cleaners, red pom-pom, and silver headband.", "Pull the dresses and the white and brown clothes from closets. The snow princess just wears her dress, no crafting needed.", "Ice queen: spread the silver glitter glue in thin lines along the neckline and sleeves of the blue dress. Let it dry flat for one hour.", "Safety: cut slowly and keep fingers clear of the scissors.", "Snowman: tape the 3 black felt circles down the front of the white shirt as coal buttons. Reindeer: twist the 2 brown pipe cleaners into antler shapes and tape them to the silver headband. Tape the red pom-pom over the nose as a glowing nose.", "Wear each outfit with its accessories. The ice queen adds the silver headband as a tiara."]}, "sushi-roll": {"m": ["1 white bedsheet or large white t-shirt to wear (make: from closet)", "Dark green felt sheet, 1 large (buy: craft store; construction paper works too)", "Pink or orange felt sheet, 1 large (buy: craft store)", "White pom-poms, 4 large, plus 1 green pom-pom (buy: craft store; cotton balls work too)", "1 pair of toy chopsticks or 2 wooden sticks (buy: toy store or craft store; pencils work too)", "Fabric glue (buy: craft store)"], "s": ["Buy the green and pink felt, the pom-poms, the toy chopsticks, and the fabric glue.", "Dress in the white bedsheet or large white t-shirt.", "Safety: cut the felt slowly and keep fingers clear of the scissors.", "Make the wrap: cut the dark green felt sheet into a wide band that goes around your waist. Glue or pin it there as the seaweed wrap.", "Make the toppings: cut the pink felt sheet into long strips and glue them across the white shirt as salmon. Glue the white pom-poms near the shoulder as rice balls and the green pom-pom as wasabi.", "Finishing touch: carry the toy chopsticks in one hand like you are about to pick up a bite."]}, "deviled-egg": {"m": ["1 white t-shirt (buy: craft store or use one you own)", "1 sheet yellow felt (buy: craft store; construction paper works too)", "2 red felt sheets or red fabric for the tail (buy: craft store; construction paper works too)", "Red headband (buy: dollar store)", "2 red pipe cleaners (buy: craft store; twisted strips of red paper work too)", "Scissors, tape or glue", "Red face paint or lipstick (buy: drugstore)"], "s": ["Buy the white t-shirt, yellow felt, red headband, and red pipe cleaners.", "Safety: adults handle the scissors when cutting the felt.", "Cut a large egg-yolk oval from the yellow felt, about dinner-plate size.", "Tape or glue the yellow felt oval to the chest of the white t-shirt.", "Twist the two red pipe cleaners into small horns, and tape them to the red headband.", "Cut a long pointed tail from the red felt sheets, and tape it to the back of the white t-shirt. Add red face paint spots if you like."]}, "pizza-slice": {"m": ["Large cardboard box, 1 (make: cut a big triangle, about 3 feet tall)", "Yellow and orange acrylic paint (buy: craft store)", "Red felt, 1 sheet (buy: craft store; red paper works too)", "Brown felt scraps for crust, or a brown paper bag (buy: craft store)", "Paintbrush, scissors, tape (make: household tools)", "Fabric glue (buy: craft store)"], "s": ["Buy the yellow and orange acrylic paint, red felt, and fabric glue. Cut the big triangle from the large cardboard box with the scissors. Round off the wide end for the crust.", "Paint the whole triangle a golden yellow-orange with the paintbrush and let it dry 1 hour.", "Cut red felt circles for pepperoni and a brown strip from the brown felt scraps for the crust. Glue them on with the fabric glue.", "Tape two string loops to the back so it wears like a sandwich board. Keep the crust at the top and the point at the bottom."]}, "popcorn-bucket": {"m": ["Cardboard box, 1 medium (make: tall enough to cover the torso)", "Red and white striped wrapping paper or paint (buy: dollar store or craft store)", "Yellow or white balloons, 8 to 10 (buy: dollar store)", "Tape, string, scissors (make: household tools)", "Red marker for the label (make: household)"], "s": ["Buy the red and white striped wrapping paper and the yellow or white balloons. Wrap the cardboard box in red-and-white stripes and write 'POPCORN' big across the front with the red marker.", "Cut head and arm holes in the cardboard box with the scissors so it wears like a barrel. Tape the inside edges of the holes so the cardboard does not scratch.", "Blow up the yellow or white balloons and tie them in a cluster. Tie the cluster to a string ring that sits on top of the box like overflowing popcorn.", "Step into the box and pull the string straps over the shoulders. Carry the popcorn crown carefully through doorways."]}, "ice-cream-cone": {"m": ["1 tan paper party hat or cone (buy: dollar store)", "1 white t-shirt (buy: craft store or use one you own)", "Colored dot stickers or pom-poms for sprinkles (buy: craft store; cut paper dots work too)", "Brown paint or marker for the cone crosshatch (buy: craft store)", "Tape (make: use what you own)"], "s": ["Buy the tan paper party hat, the white t-shirt, the dot stickers, and the brown marker.", "Draw a waffle-cone crosshatch on the tan paper party hat with the brown marker.", "Set the tan paper party hat on the head like a hat, and tape the elastic so it sits snugly.", "Safety: keep small pom-poms away from kids under three, since they are a choking hazard.", "Cover the white t-shirt with the colored dot stickers or pom-poms, scattered like sprinkles.", "Keep the stickers off the skin."]}, "pbj": {"m": ["Brown t-shirt (buy: thrift store or closet)", "Purple t-shirt (buy: thrift store or closet)", "White poster board, 2 sheets (buy: dollar store)", "Markers (make: household)", "Scissors and tape or string (make: household tools)"], "s": ["Buy the brown t-shirt, purple t-shirt, and white poster board. Cut two big sandwich-bread shapes from the white poster board with the scissors.", "Write 'PB' in big letters on one bread shape and 'J' on the other with the markers.", "Tape or string one bread sign to the front of the brown t-shirt. Tape or string the other to the front of the purple t-shirt.", "Stand pressed together all evening, bread sides out. The brown-shirt person is the peanut butter and the purple-shirt person is the jelly."]}, "bacon-eggs": {"m": ["Dark red or brown shirt for the bacon (own)", "White shirt for the egg (own)", "1 sheet red-brown craft felt (buy: craft store, construction paper works too)", "1 sheet each white and yellow craft felt (buy: craft store, construction paper works too)", "Safety pins (buy: dollar store)", "Scissors"], "s": ["Buy the craft felt and the safety pins.", "Cut 4 wavy vertical strips from the red-brown craft felt with the scissors. Cut one large white oval and one yellow circle from the other felt sheets.", "Pin the wavy strips down the front of the dark red or brown shirt with a safety pin.", "Pin the white oval to the white shirt, then pin the yellow circle on top of it for the yolk.", "Put on the shirts. Have the bacon stand just behind the egg for photos, yolk side out."]}, "peas-pod": {"m": ["Green t-shirts, 1 per person, 3 to 5 people (buy: thrift store or closet)", "Green felt, 1 yard (buy: craft store; green fabric works too)", "Green fabric paint (buy: craft store)", "Hot glue gun or fabric glue (buy: craft store)", "Green face paint (buy: drugstore)", "Scissors (make: household tools)"], "s": ["Buy the green felt, green fabric paint, and hot glue gun from the store. Cut the green felt into one long pod shape with the scissors, about 6 feet long, with a pointed top.", "Paint darker green stripes and a center seam line down the pod with the green fabric paint. Let the paint dry for 1 hour.", "Safety: let an adult handle the hot glue gun, and keep fingers away from the nozzle.", "Glue the pod to the front of the green t-shirts so it stretches across all of them. Space the wearers evenly.", "Paint a small green circle on each person's cheek with the green face paint. Line everyone up in height order under the pod and walk together in a row."]}, "basketball-star": {"m": ["Basketball jersey or numbered tank top (own, or buy: sporting goods store)", "Basketball shorts (own)", "Black non-toxic face paint or eyeliner pencil (buy: toy store)", "Basketball (own, or buy: toy store)"], "s": ["Pull on the basketball jersey and the basketball shorts.", "Safety: use only the black non-toxic face paint. Skip the eye black for very young kids who will rub their eyes.", "Draw two short black stripes under each eye with the black non-toxic face paint.", "Carry the basketball everywhere, tucked under one arm.", "Dribble it whenever you stand still."]}, "referee": {"m": ["Plain black t-shirt or long-sleeve shirt (make: from closet)", "Black pants or shorts (make: from closet)", "White athletic tape, 1 roll (buy: sporting goods or pharmacy)", "Plastic whistle (buy: dollar store or sporting goods)", "Yellow fabric square, 6 inches (make: cut from an old cloth or napkin)"], "s": ["Buy the whistle, white athletic tape, and check you have a black shirt and pants ready.", "Tear horizontal strips of the white athletic tape across the front and back of the black shirt. Space them about 2 inches apart and press firmly so they stay.", "Fold the yellow fabric square in half and tie it in a knot around the whistle lanyard. Or tape it to the whistle so it waves when you blow the whistle.", "Wear the black outfit with the striped shirt and put the whistle around your neck. Tuck the yellow flag in a pocket."]}, "boxer": {"m": ["Bathrobe (own)", "Toy boxing gloves (buy: toy store)", "Purple and yellow non-toxic face paint (buy: toy store)", "Athletic shorts and sneakers (own)", "Phone for entrance music (own)"], "s": ["Buy the toy boxing gloves and the purple and yellow non-toxic face paint.", "Pull on the athletic shorts, sneakers, and bathrobe with the hood up.", "Safety: keep the face paint clear of the eyes.", "Dab the purple and yellow face paint on one cheekbone and around one eye for bruise makeup.", "Pull on the toy boxing gloves.", "Throw a few shadow punches and play entrance music from the phone as you walk in."]}, "cheerleader": {"m": ["Team-color t-shirt and skirt or shorts (own)", "4 to 6 white plastic grocery bags (make: save from home)", "Hair ribbon in a team color (buy: dollar store)", "Rubber bands or tape (own)", "Scissors"], "s": ["Safety: cut the bags up right away. Keep whole bags away from very small children.", "Stack 2 to 3 white plastic grocery bags. Cut them into long strips with the scissors, stopping 3 inches from one end.", "Roll the uncut end tightly and wrap it with a rubber band or tape to make a handle. Fluff the strips.", "Make a second pom-pom the same way.", "Pull on the team-color t-shirt and skirt or shorts. Tie the hair ribbon in a bow and carry a pom-pom in each hand."]}, "tennis-duo": {"m": ["White t-shirts and white shorts or skirts, one set each (make: from closet)", "2 white sweatbands or strips of white fabric (buy: sports store)", "2 toy tennis rackets (buy: toy store; cardboard rackets work too)", "1 tube of tennis balls (buy: sports store)", "White socks and sneakers (make: from closet)"], "s": ["Buy the toy tennis rackets, tube of tennis balls, and sweatbands.", "Pull the white outfits and sneakers from the closet.", "Dress head to toe in white and tie the sweatband across the forehead.", "Safety: cut the fabric slowly and keep fingers clear of the scissors.", "To make a sweatband: cut a 2-inch strip of white fabric. Tie it around the head with a knot at the back.", "Finishing touch: carry the toy tennis rackets and tuck the tube of balls under one arm for the courtside pose."]}, "bowling-pins": {"m": ["White shirt and pants per pin person (own)", "Red duct or electrical tape (buy: dollar store)", "Black shirt and pants for the bowler (own)", "Toy bowling ball or black playground ball (buy: toy store)", "Scissors"], "s": ["Buy the red duct or electrical tape and the toy bowling ball.", "Each pin person cuts two red tape stripes from the roll with the scissors.", "Wrap two red tape stripes around the collar of the white shirt and one around each wrist.", "The bowler pulls on the black shirt and pants.", "Safety: use a lightweight toy ball, never a real bowling ball.", "Carry the toy bowling ball. Line the pins up in formation with the bowler at the end for photos."]}, "cardboard-knight": {"m": ["Large cardboard boxes (make: collect spares)", "Silver acrylic paint (buy: craft store, tempera paint works too)", "Foam brush or paintbrush (own, or buy: craft store)", "1 pool noodle (buy: toy store or dollar store)", "Gray duct tape (buy: dollar store)", "Black marker (buy: dollar store)", "Scissors"], "s": ["Safety: an adult should handle the heavy cutting. Cut generous eye holes in the helmet so vision stays clear.", "Cut a chest plate, back plate, two shoulder pieces, and a helmet from the large cardboard boxes with the scissors.", "Paint every armor piece silver with the silver acrylic paint and the foam brush. Let the paint dry fully.", "Add rivet dots and edge lines with the black marker.", "Tape the plates together with the gray duct tape so they hinge at the shoulders. Wrap the pool noodle in gray duct tape for the sword.", "Put the armor on over dark clothes once the paint is dry. Carry the noodle sword."]}, "ninja": {"m": ["All-black outfit: t-shirt, pants, and a black beanie (make: from closet)", "Black belt or sash, 1 (make: an old tie or scarf)", "Black headband or strip of black t-shirt, 1 (make: cut from an old shirt)", "Scissors and tape (make: household tools)", "Black face paint for a mask stripe (buy: drugstore, optional)"], "s": ["Pull the all-black outfit from the closet. Cut a 3-inch-wide strip from an old black t-shirt with the scissors for the black headband. Put on the black beanie.", "Tie the black sash around the waist with the knot at the back, and tuck the ends in.", "Safety: keep the eyes and mouth uncovered, and wrap the black headband above the eyes.", "Wrap the black headband around the forehead and tie it at the back, leaving the eyes clear.", "Paint a thin black stripe across the bridge of the nose with the black face paint. Practice the silent sneaky walk."]}, "caped-duo": {"m": ["2 old twin sheets or large fabric rectangles (make: cut from old sheets)", "Craft felt for masks and emblems (buy: craft store, construction paper works too)", "Ribbon or cord for cape ties (own, or buy: craft store)", "Fabric glue (buy: craft store)", "Paper and pencil for sketching (own)", "Scissors"], "s": ["Sketch a matching emblem for each of you on the paper.", "Cut the emblems from the craft felt with the scissors.", "Cut each sheet into a cape with the scissors. Glue a craft felt emblem to the back of each cape with the fabric glue.", "Cut two eye masks from the craft felt, cutting the eye holes wide. Glue ribbon ties to the ends with the fabric glue and let the glue dry.", "Safety: tie the cord in a loose bow that pulls free easily. Never tie anything tight around the neck. Keep the mask eye holes wide so vision stays clear.", "Tie the capes at the neck with the cord in a loose bow and put on the masks."]}, "hero-squad": {"m": ["1 cape per person in squad colors (buy: craft store, or make from 1 yard of fabric each)", "1 mask per person, matching the cape color (buy: craft store)", "1 t-shirt per person in the cape color (buy: craft store)", "Fabric paint for the team emblem (buy: craft store)", "Safety pins (make: use what you own)"], "s": ["Buy the capes, masks, t-shirts, and fabric paint in the squad color.", "Each hero paints the same team emblem, like a lightning bolt, on the t-shirt with the fabric paint.", "Let the fabric paint dry fully before wearing.", "Safety: keep each cape short enough to clear the ground so nobody trips.", "Pin each cape at the shoulders with a safety pin, and wear the matching mask.", "End every appearance with the team pose: fists on hips, capes billowing."]}, "astronaut": {"m": ["White sweatshirt and sweatpants (buy: clothing store, or use your own)", "1 large brown paper bag (buy: grocery store or craft store)", "Silver duct tape (buy: dollar store)", "Flag sticker or iron-on patch (buy: craft store)", "Scissors"], "s": ["Buy the white sweatshirt and sweatpants, paper bag, silver duct tape, and flag sticker.", "Cut a wide face opening in the paper bag with the scissors.", "Wrap two silver duct tape stripes around each sleeve and pant leg. Press the flag sticker onto the chest of the sweatshirt.", "Safety: cut the face opening wide enough that vision and hearing stay clear.", "Pull on the white sweatshirt and sweatpants.", "Slip the bag over your head so the face opening lines up. Crimp the top with a strip of duct tape so it holds its shape."]}, "robot-ranger": {"m": ["1 medium cardboard box for the torso (make: from home)", "Aluminum foil, 1 roll (buy: grocery store)", "Dryer vent hose, 1 flexible aluminum section (buy: hardware store)", "Sticker dots or round stickers, 1 sheet (buy: craft store; punched paper circles work too)", "Duct tape, 1 roll (buy: hardware store)", "Blue or gray sweatsuit to wear underneath (make: from closet)", "Black marker, 1 (make: from home)"], "s": ["Buy the aluminum foil, dryer vent hose, sticker dots, and duct tape.", "Safety: cut the cardboard box slowly and keep fingers clear of the scissors. The dryer vent hose has sharp wire edges, so cut carefully and tape the ends right away.", "Cut head and arm holes in the medium cardboard box. Wrap it in aluminum foil like a gift, taping the foil flat.", "Draw two round gauges on the foil chest with the black marker. Stick the sticker dots on as dial needles and button lights.", "Cut the dryer vent hose into two arm-length pieces and tape the ends so the wire ribs stay put. Tape the top of each piece to the shoulder holes of the cardboard box so arms slide inside.", "Dress in the blue or gray sweatsuit and slide the foil-wrapped cardboard box over the head and arms. Press the sticker dials on last so they sit on the chest."]}, "penguin-huddle": {"m": ["Black long-sleeve shirts, 1 per person (buy: thrift store or closet)", "White felt, 1 sheet per person (buy: craft store; white paper works too)", "Orange felt, 1 sheet per person (buy: craft store; orange paper works too)", "Headbands, 1 per person (buy: dollar store)", "Fabric glue (buy: craft store)", "Scissors (make: household tools)"], "s": ["Buy the white felt, orange felt, headbands, and fabric glue. Cut an oval white belly from the white felt with the scissors for each person.", "Cut a small orange triangle beak from the orange felt for each headband. Glue one beak to the front of each headband with the fabric glue.", "Glue the white bellies to the front of the black long-sleeve shirts. Let the fabric glue dry for 30 minutes.", "Each person: put on the black long-sleeve shirt and the headband with the beak. Tuck hands into the sleeves as flippers and waddle shoulder to shoulder in the huddle."]}, "prince-princess": {"m": ["Gold paper crown or plastic crown (buy: dollar store, or make: cut one from gold poster board)", "Cape or long piece of fabric, 1 (buy: thrift store)", "Thrifted gown or long dress, 1 (buy: thrift store)", "Tiara (buy: dollar store)", "Toy scepter or wand (buy: dollar store)"], "s": ["Buy the gold paper crown, tiara, and toy scepter. Pick up the thrifted gown and cape at the thrift store.", "The prince: wear the gold paper crown and cape over dark clothes, and carry the toy scepter.", "The princess: wear the thrifted gown and tiara, and add the spare wand if there is one.", "Walk in with royal posture, wave slowly with a bent wrist, and address everyone as 'my good subject'."]}, "dino-herd": {"m": ["1 green poncho or green bedsheet per person (buy: craft store or online)", "1 sheet green felt per person (buy: craft store; construction paper works too)", "1 old white or colored sock per person (make: use one you own)", "Scrap fabric or cotton balls for stuffing (make: use what you own)", "Fabric glue or safety pins", "Scissors"], "s": ["Buy one green poncho and one green felt sheet per person, and raid the sock drawer for an old sock.", "Safety: adults handle the scissors when cutting the green felt.", "Cut triangles from the green felt for the back spikes.", "Pin the green felt triangles in a row down the back of the green poncho.", "Stuff the old sock with the scrap fabric, and pin the opening to the back waistband of the green poncho.", "Wear the green poncho over a t-shirt and jeans. Pin the spikes and tail flat so they do not poke anyone in a crowd."]}, "pixel-ghost": {"m": ["White bedsheet or white fabric, 1 twin-size (buy: thrift store)", "Black felt, 1 sheet (buy: craft store; black paper works too)", "Fabric glue (buy: craft store)", "Scissors (make: household tools)", "Marker and ruler (make: household)"], "s": ["Buy the white bedsheet and the black felt. Fold the white bedsheet in half. Cut the bottom edge into chunky square zigzags with the scissors, about 4 inches per square.", "Draw two square eyes and a square mouth on the black felt with the marker and ruler. Cut them out.", "Glue the felt eyes and mouth onto the top third of the white bedsheet. Let the fabric glue dry for 30 minutes.", "Safety: keep the eye area open so vision stays clear.", "Wear dark clothes underneath and drape the white bedsheet over the head with the eyes lined up. Cut two small arm slits if reaching through is hard."]}, "spaghetti-meatball": {"m": ["White t-shirt or sweatshirt (make: from closet)", "Yellow or cream yarn, 1 skein (buy: craft store)", "3-4 brown pom-poms, 2 inch (buy: craft store)", "Fabric glue or hot glue gun (buy: craft store)"], "s": ["Lay the white shirt flat.", "Cut yarn into 12-inch strands. Glue them across the shirt in wavy rows to look like spaghetti.", "Glue 3-4 brown pom-poms on top as meatballs.", "Let dry completely before wearing."]}, "cupcake": {"m": ["Brown t-shirt or tunic for the wrapper (make: from closet)", "White pillowcase for the frosting (make: from home)", "Red pom-pom or ball for the cherry (buy: craft store)", "Fabric glue (buy: craft store)"], "s": ["Put on the brown shirt. This is the cupcake wrapper.", "Drape the white pillowcase over your head and shoulders like frosting. Trim eye holes if needed.", "Glue the red pom-pom on top as the cherry.", "Fluff the pillowcase edges to look like frosting swirls."]}, "banana": {"m": ["Yellow sweatshirt and sweatpants (make: from closet, or buy: clothing store)", "Green felt, 1 sheet (buy: craft store)", "Headband (buy: dollar store)", "Fabric glue (buy: craft store)"], "s": ["Put on the yellow sweatshirt and sweatpants.", "Cut a stem shape from green felt, about 4 inches tall.", "Glue the stem to the headband.", "Wear the headband. You are a banana."]}, "hot-dog": {"m": ["Red t-shirt (make: from closet)", "Tan or beige foam pool noodle, cut in half lengthwise (buy: dollar store)", "Yellow fabric paint for mustard (buy: craft store)", "Safety pins or fabric glue (buy: craft store)"], "s": ["Put on the red shirt. You are the hot dog.", "Cut the pool noodle in half lengthwise to make two bun halves.", "Paint a mustard squiggle down one bun half with yellow fabric paint. Let dry.", "Attach the bun halves to your sides with safety pins or fabric glue, one on each side."]}, "donut": {"m": ["Large cardboard box or foam board (make: from home)", "Pink paint (buy: craft store)", "Multicolor sprinkles: cut from felt or use stickers (buy: craft store)", "Ribbon or string to wear it (make: from home)"], "s": ["Cut a large donut shape from cardboard: a circle with a hole in the middle, big enough to fit over your head.", "Paint it pink. Let dry.", "Glue on felt sprinkles or stickers in bright colors.", "Attach ribbon to the top so you can wear it like a sandwich board."]}, "coffee-cup": {"m": ["White trash bag or white sheet (make: from home)", "Cardboard tube or large cylinder (make: from home)", "Brown paper or felt for the lid (buy: craft store)", "Brown marker (buy: dollar store)"], "s": ["Cut holes in the white trash bag for head and arms. This is the cup.", "Draw a coffee shop logo on the front with brown marker.", "Make the lid: cut a brown paper circle bigger than your head, with a sip hole.", "Wear the bag, then the lid hat on top."]}, "salt-pepper": {"m": ["White shirt, pants, and hat for the Salt (make: from closet)", "Black shirt, pants, and hat for the Pepper (make: from closet)", "Cardboard for 2 shaker tops (make: from home)", "Gray paint or gray marker for the shaker tops (buy: craft store)", "Black marker for the S and P (make: from home)", "Tape or glue (make: from home)"], "s": ["Salt dresses all in white, Pepper all in black.", "Cut two shaker tops from cardboard: a short wide cylinder or dome each, big enough to sit on a hat.", "Paint them gray and dot holes on top like a real shaker. Let dry.", "Tape each top to a hat so it rides on your head.", "Write a big S on Salt's shaker and a big P on Pepper's with black marker."]}, "fruit-salad": {"m": ["Solid-color outfits in fruit colors: red, yellow, green, orange (make: from closet)", "Green felt for leaf hats, 1 sheet per person (buy: craft store)", "Headbands, 1 per person (buy: dollar store)", "Fabric glue (buy: craft store)"], "s": ["Each person picks a fruit and wears that color head to toe. Red for strawberry, yellow for banana, green for lime, orange for orange.", "Cut leaf shapes from green felt.", "Glue one leaf to each headband.", "Everyone wears their headband. Take a group photo as the fruit salad."]}, "wizard": {"m": ["1 tall black pointy wizard hat (buy: costume aisle or craft store)", "1 long plain black robe or black graduation gown (make: from closet, or buy: thrift store)", "1 tall straight wooden staff, about 5 feet tall (make: from a dowel or sturdy branch, or buy: craft store)", "Gray face paint or a stick-on gray beard, optional (buy: costume aisle)", "1 belt or rope sash (make: from closet)"], "s": ["Buy the wizard hat if needed. Pull a long plain black robe or gown from the closet.", "Safety: keep the hat brim above the eyes so vision stays clear, and carry the staff upright. Never swing it at anyone.", "Draw on a gray beard with the face paint, or stick on the fake beard.", "Tie the belt or rope sash around the waist over the robe.", "Put on the pointy hat last, tap the staff on the ground, and strike a pose."]}, "toy-box-crew": {"m": ["Cowboy hat and cow-print vest for the sheriff (buy: costume aisle or thrift store)", "White shirt and pants with purple felt accents for the space ranger (make: from closet)", "Cardboard wings and a clear plastic dome for the space ranger helmet (make: from craft supplies)", "Brown boots or boot covers for the sheriff (make: from closet)", "Yellow shirt with a hand-drawn star badge for extra toy-box friends (make: from closet)", "Toy pull-string name tags, 1 per person (make: index cards)"], "s": ["Buy the cowboy hat, cow-print vest, purple felt, and clear plastic dome. Pull white clothes for the space ranger, brown boots for the sheriff, and a yellow shirt for extra toy-box friends from the closet.", "Sheriff: wear the cowboy hat, cow-print vest, and brown boots. Draw a star badge on the yellow shirt with a marker.", "Space ranger: cut purple felt fins and buttons and glue them to the white shirt. Tape the cardboard wings to the back and wear the clear plastic dome as a helmet.", "Safety: keep the plastic dome above the shoulders with the face fully open, and carry any toy props low so nobody gets poked.", "Tie a pull-string name tag to each wrist. Strike the sheriff pose and the space-ranger landing pose for the group photo."]}, "demon-boy-band": {"m": ["Matching streetwear per person: oversized black or white t-shirt and baggy pants (make: from closet)", "Neon fabric paint in 2 colors (buy: craft store)", "Temporary tattoos or neon eyeliner (buy: drugstore)", "Toy microphones (buy: dollar store)", "Hair gel for the swept idol look (make: from the bathroom)", "Sunglasses for the stage-photo pose (make: from the drawer, optional)"], "s": ["Buy the neon fabric paint, temporary tattoos, toy microphones, and hair gel. Lay out the matching black or white outfits.", "Paint matching glowing patterns on everyone: lightning marks on the sleeves, circles on the chest. Let the paint dry for 2 hours.", "Apply neon eyeliner or temporary tattoos on cheeks and hands. Style hair up and forward with the gel.", "Safety: keep paint off faces and away from eyes.", "Wear the matching streetwear, carry a toy microphone each, line up shoulder to shoulder, and strike the synchronized album-cover pose."]}, "dragon-rider-duo": {"m": ["Brown t-shirt and dark pants for the rider (make: from closet)", "Gray felt or an old gray blanket for the dragon tunic (buy: craft store or thrift store)", "Large cardboard box for dragon wings and tail (make: collect spares)", "Black and yellow craft foam for dragon eyes (buy: craft store)", "Faux-fur vest or brown scarf for the viking look (make: from closet)", "Scissors, tape, and string (make: household tools)"], "s": ["Buy the gray felt, craft foam, scissors, and tape. Pull the brown t-shirt, dark pants, and faux-fur vest from the closet.", "Cut two big wing shapes and a long tail from the cardboard box. Tape the wings to the back and the tail to the waist of the dragon person's gray felt tunic.", "Glue the black and yellow foam eyes to a headband for the dragon head. The rider wears the faux-fur vest over the brown t-shirt.", "Safety: keep wing tips above waist height and tape all cardboard edges smooth so nobody gets scratched.", "Rider stands in front with arms out like steering; dragon crouches behind with wings spread. Take the flying photo."]}, "numbered-players": {"m": ["Green sweatsuit per person (buy: thrift store, or make: from closet)", "White t-shirt per person (make: from closet)", "Iron-on number patches or white paper numbers, 1 per person (buy: craft store)", "White sneakers (make: from closet)", "Dalgona candy or a round cookie per person (buy: bakery, optional prop)", "Iron (make: household)"], "s": ["Buy the green sweatsuits and number patches. Pull white t-shirts and white sneakers from the closet.", "Iron or tape one number onto the front of each white t-shirt and the matching number on the back.", "Wear the white t-shirt under the green sweatsuit jacket with the number showing, plus the white sneakers.", "Hand each player a dalgona candy as the prop. Line up in number order for the photo.", "Safety: if using an iron, have an adult do the pressing. Keep numbers readable and identical front and back."]}, "emotion-crew": {"m": ["One solid bright color outfit per person: yellow, blue, red, green, purple, or orange (make: from closet)", "Face paint matching each outfit color (buy: drugstore)", "White poster board for emotion name signs (buy: dollar store)", "Markers (make: household)", "Colored hair spray matching each outfit, optional (buy: drugstore)"], "s": ["Pull one loud solid-color outfit per person from the closet. Buy the face paint, poster board, and markers.", "Each person picks an emotion and writes it big on poster board: Joy, Sadness, Anger, Fear, Disgust, Anxiety, Envy, Embarrassment, Ennui.", "Paint a simple face design in the matching color: a big smile, a tear, furrowed brows. Mist hair with the matching color spray if you like.", "Wear the full monochrome outfit with the emotion sign. Group up in a row like the control panel."]}, "kart-racers": {"m": ["Large cardboard box per racer (make: collect spares)", "Red, blue, green, and yellow paint or wrapping paper (buy: dollar store)", "Paper plates for wheels, 4 per kart (buy: dollar store)", "Racing cap or helmet per person (make: from closet)", "Scissors, tape, and string (make: household tools)", "Ribbon for kart straps (make: from closet)"], "s": ["Buy the paint or wrapping paper and paper plates. Collect one large box per racer.", "Cut the top and bottom out of each box so it fits around the torso like a kart. Paint each kart a different bright color.", "Tape two paper-plate wheels to each side. Tape ribbon straps inside so the kart hangs at waist height.", "Safety: keep the kart box at waist height so legs move freely, and tape all cut edges smooth.", "Wear the kart with the racing cap, line up side by side, and strike the starting-grid pose."]}, "tall-hat-crew": {"m": ["Tall red-and-white striped stovepipe hat (buy: costume aisle, or make: poster board)", "Red bow tie (buy: dollar store, or make: paper)", "Black shirt and pants for the cat (make: from closet)", "Red jumpsuits or red shirts and pants for the Things (make: from closet)", "Blue wigs for the Things, 2 (buy: costume aisle)", "Iron-on letters or paper that says Thing 1 and Thing 2 (buy: craft store)"], "s": ["Buy the striped hat, blue wigs, red bow tie, and iron-on letters. Pull black and red clothes from the closet.", "Cat: wear the black shirt and pants, the tall striped hat, and the red bow tie.", "Things: wear the red jumpsuits with the blue wigs. Iron or tape Thing 1 and Thing 2 onto the chests.", "The Things bounce and cause trouble; the cat looks worried. That is the whole photo."]}, "chipmunk-trio": {"m": ["Red, blue, and green sweaters or sweatshirts (buy: thrift store)", "Iron-on letters A, S, T (buy: craft store)", "Brown felt for ears, 3 pairs (buy: craft store)", "Headbands, 3 (buy: dollar store)", "Brown eyeliner for whiskers and a nose (buy: drugstore)", "Fabric glue (buy: craft store)"], "s": ["Buy the sweaters, iron-on letters, brown felt, headbands, and brown eyeliner.", "Iron A onto the red sweater, S onto the blue, T onto the green. Let them cool flat.", "Cut round chipmunk ears from the brown felt and glue one pair to each headband.", "Wear the letter sweaters with the ear headbands. Draw three whisker dots and a nose on each cheek with the brown eyeliner.", "Line up tallest to shortest and sing one note together for the photo."]}, "galaxy-knights": {"m": ["Brown or beige bathrobe or long coat per knight (make: from closet)", "Toy energy-blade prop per knight (buy: toy store)", "Wide belt or rope sash per knight (make: from closet)", "Dark pants and boots (make: from closet)", "Brown face paint for a hood shadow, optional (buy: drugstore)"], "s": ["Buy the toy energy-blade props. Pull the bathrobes, belts, dark pants, and boots from the closet.", "Wear the bathrobe over dark pants with the belt tied at the waist. Pull the hood up.", "Carry the energy blade unlit until the photo. Two stances: blade up ready, or blade down calm.", "Safety: keep the toy blades pointed up or down, never at faces. Sparring stays slow and pretend.", "Line up the knights in a row, ignite the blades, and take the council photo."]}, "plastic-dream-crew": {"m": ["All-pink outfit per person: dress, suit, or sweatsuit (make: from closet)", "Pink sunglasses per person (buy: dollar store)", "Plastic play accessories: phone, tiara, handbag (make: from the toy box)", "Pink feather boa, 1 to share (buy: dollar store, optional)", "Blonde wig, optional (buy: costume aisle)"], "s": ["Pull an all-pink outfit per person from the closet. Buy the pink sunglasses and feather boa.", "Everyone wears pink head to toe with the pink sunglasses. Add the tiara, handbag, or toy phone.", "Drape the feather boa over whoever is feeling the most plastic today.", "Strike the wave-and-smile pose. Everything is pink, and that is the whole point."]}, "extinct-party-animal": {"m": ["Jacket or blazer you own (own)", "1 sheet green craft felt (buy: craft store, construction paper works too)", "Party hat (buy: dollar store or party aisle)", "Blank name badge (buy: office supply aisle)", "Fabric glue (buy: craft store)", "Marker", "Scissors"], "s": ["Buy the green craft felt, party hat, blank badge, and fabric glue.", "Cut 6 to 8 triangle spikes from the green craft felt with the scissors.", "Glue the spikes in a row along the shoulders of the jacket. Let dry 15 minutes.", "Write 'Last seen 66 million years ago' on the badge with the marker.", "Pin on the badge, put on the party hat, and work the room."]}, "dino-tourist": {"m": ["Hawaiian shirt (buy: thrift store, or own)", "Fanny pack (own, or buy: thrift store)", "Plush dinosaur tail (buy: toy store or online)", "Toy camera (own, optional)", "Sunglasses (own, optional)"], "s": ["Pull the Hawaiian shirt and fanny pack from the closet.", "Clip or pin the plush tail to your waistband at the back.", "Hang the toy camera around your neck.", "Put on the sunglasses, ask strangers to take your picture, and complain about the meteor."]}, "raptor-barista": {"m": ["Green hoodie (buy: clothing store, or use your own)", "Toy T. rex arms (buy: toy store or online)", "Paper coffee cup (make: from home)", "Brown eyeliner for the snout (buy: drugstore, optional)"], "s": ["Buy the green hoodie and toy T. rex arms.", "Put on the green hoodie with the hood up.", "Strap the tiny T. rex arms over your own arms at the elbows.", "Grab the paper coffee cup with the tiny arms and serve."]}, "emotional-support-dinosaur": {"m": ["Vest or sleeveless jacket you own (own)", "1 sheet green craft felt (buy: craft store, construction paper works too)", "Blank badge or pin (buy: office supply aisle)", "Fabric glue (buy: craft store)", "Marker", "Scissors"], "s": ["Buy the green craft felt, blank badge, and fabric glue.", "Cut 6 to 8 triangle spikes from the green craft felt with the scissors.", "Glue the spikes along the vest shoulders and back. Let dry 15 minutes.", "Write 'Emotional Support Dinosaur. Do not pet.' on the badge with the marker.", "Pin it on and refuse all pets."]}, "garden-fairy": {"m": ["Pink tulle (buy: craft store)", "Large cardboard for wings (make: from a shipping box)", "Fake flowers (buy: dollar store)", "Headband (buy: dollar store, or use your own)", "Wooden dowel or stick for the wand (make: from the yard)", "Cardboard star for the wand tip (make: from scraps)", "Elastic for wing straps (buy: craft store)", "Tape", "Glue", "Scissors"], "s": ["Buy the pink tulle, fake flowers, headband, and elastic.", "Cut two large wing shapes from the cardboard with the scissors.", "Cover each wing with pink tulle and tape the edges down.", "Glue fake flowers around the headband for the crown.", "Tape the cardboard star to the top of the dowel for the wand.", "Safety: keep the wand away from faces during photos.", "Tape elastic straps to the back of the wings and slip arms through."]}, "ballerina": {"m": ["Pink tulle (buy: craft store)", "Wide elastic cut to waist size (buy: craft store)", "Pink leotard or fitted shirt (own, or buy: clothing store)", "Pink tights (own, or buy: clothing store)", "Hair ties and bobby pins (own)", "Scissors"], "s": ["Buy the pink tulle and wide elastic. Pull the leotard and tights from the closet.", "Cut the tulle into long strips with the scissors.", "Tie strips around the elastic, snug and side by side, until the tutu looks full.", "Safety: tie the elastic snug enough to stay up while twirling.", "Wear the tutu over the leotard and tights.", "Pull hair into a high bun with the hair ties and bobby pins."]}, "butterfly": {"m": ["Large cardboard for wings (make: from a shipping box)", "Acrylic paint set (buy: craft store)", "Black sweatsuit (own, or buy: clothing store)", "Elastic for wing straps (buy: craft store)", "Headband (buy: dollar store, or use your own)", "Pipe cleaners for antennae (buy: craft store)", "Tape", "Scissors"], "s": ["Buy the paint, elastic, headband, and pipe cleaners. Pull black sweats from the closet.", "Cut two big wing shapes from the cardboard with the scissors.", "Paint both wings with bright patterns and let them dry flat.", "Tape elastic loops to the back of each wing for the arms.", "Bend pipe cleaners into antennae and tape them to the headband.", "Safety: keep wing edges away from doorways; turn sideways to pass through.", "Wear the wings over the black sweats with the antennae headband."]}, "pop-star": {"m": ["Sparkly or sequin jacket (buy: thrift store)", "Toy microphone (buy: toy store or dollar store)", "Hair teasing comb (own, or buy: drugstore)", "Sunglasses (own, or buy: dollar store)", "Dark jeans and a dark top (own)"], "s": ["Buy the sparkly jacket, toy microphone, and sunglasses.", "Tease the hair big with the comb.", "Safety: go easy teasing near the scalp; no pulling hard.", "Wear the sparkly jacket over the dark jeans and top.", "Put on the sunglasses.", "Carry the toy microphone everywhere and take requests."]}, "ice-skater": {"m": ["White dress (buy: thrift store, or own)", "White tights (own, or buy: clothing store)", "Hair donut for the bun (buy: drugstore)", "Blush (own, or buy: drugstore)", "Bobby pins (own)"], "s": ["Buy or pull the white dress, white tights, and hair donut.", "Twist the hair into a high bun around the hair donut and pin it.", "Dab a little blush on the cheeks for the cold-air glow.", "Safety: skip real skates; this costume is for dry land only.", "Wear the white dress with the tights and strike the finishing pose."]}, "ladybug": {"m": ["Red sweatsuit (own, or buy: clothing store)", "Black felt sheets (buy: craft store)", "Headband (buy: dollar store, or use your own)", "Pipe cleaners for antennae (buy: craft store)", "Fabric glue (buy: craft store)", "Scissors"], "s": ["Buy the black felt, headband, and pipe cleaners. Pull the red sweatsuit from the closet.", "Cut lots of circles from the black felt with the scissors.", "Glue the felt dots all over the red sweatsuit.", "Cut two small wing shapes from the felt scraps, dot them, and pin them at the back.", "Bend pipe cleaners into antennae and attach them to the headband.", "Safety: pin the wings where little hands cannot reach the pins.", "Wear the dotted sweats with the antennae headband."]}, "daisy": {"m": ["Yellow craft foam sheets (buy: craft store)", "Brown craft foam for the flower center (buy: craft store)", "Green dress (own, or buy: thrift store)", "Headband (buy: dollar store, or use your own)", "Glue (buy: craft store)", "Scissors"], "s": ["Buy the yellow and brown craft foam, headband, and glue.", "Cut 10 to 12 petal shapes from the yellow craft foam with the scissors.", "Glue the petals in a ring around the headband, tips pointing out.", "Glue the brown foam circle in the center of the petals.", "Safety: let the glue dry fully before wearing.", "Wear the flower headband with the green dress."]}, "little-baker": {"m": ["White paper or poster board for the hat (buy: craft store, or use printer paper)", "Apron (own, or buy: dollar store; a white t-shirt works too)", "Toy whisk (buy: toy store or dollar store)", "A pinch of flour from the kitchen (optional, for the effect)", "Tape", "Scissors"], "s": ["Buy the paper, apron, and toy whisk.", "Roll the paper into a tall chef hat shape and tape the seam.", "Trim the hat band to fit the head with the scissors.", "Safety: keep real flour away from eyes; a tiny pinch on the apron only.", "Wear the hat and the apron.", "Carry the toy whisk and offer everyone imaginary cupcakes."]}, "little-artist": {"m": ["Beret or flat cap (buy: thrift store)", "Cardboard for the palette (make: from a shipping box)", "Washable paint set (buy: craft store)", "Old smock or oversized t-shirt (own)", "Paintbrush (own, or buy: craft store)", "Scissors"], "s": ["Buy the beret and the washable paint set. Pull the old smock from the closet.", "Cut a kidney-bean palette shape from the cardboard with the scissors.", "Paint dabs of bright color around the palette edge and let dry.", "Flick a little paint onto the smock for splatters and let dry.", "Safety: use washable paint only; cover the table before splattering.", "Wear the smock and the tilted beret, and carry the palette and brush."]}};

function esc(s) {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;")
          .replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

